/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized BCD (Binary-Coded Decimal) Adder
 * 
 * This module implements a BCD adder that adds two BCD-encoded numbers. BCD uses
 * 4 bits to represent each decimal digit (0-9). The adder performs binary addition
 * and then corrects the result to ensure each digit remains in valid BCD range (0-9).
 * 
 * Algorithm:
 *   - Each BCD digit is 4 bits (represents 0-9)
 *   - Perform binary addition: binary_sum = a_digit + b_digit + carry_in
 *   - BCD correction: if binary_sum >= 10, add 6 to correct to valid BCD range
 *   - The correction ensures the result is a valid BCD digit (0-9)
 * 
 * BCD Correction Logic:
 *   - Binary addition can produce values 0-18 (with carry-in)
 *   - Valid BCD digits are 0-9
 *   - If result >= 10: add 6 to skip invalid BCD range (10-15)
 *   - Example: 9 + 1 = 10 (binary) -> 10 + 6 = 16 (binary) = 0x10 (BCD) = "10" (decimal)
 * 
 * Characteristics:
 *   - Area: Moderate - binary adders plus correction logic per digit
 *   - Delay: O(n/4) - one stage per BCD digit
 *   - Power: Moderate - correction logic adds switching
 *   - Use case: Decimal arithmetic, financial calculations, display systems
 * 
 * Note: DATA_WIDTH must be a multiple of 4 (each BCD digit is 4 bits)
 * 
 * @param DATA_WIDTH Width of input operands and sum output (must be multiple of 4, default: 32)
 */
module bcd_adder #(
    parameter DATA_WIDTH = 32    // Width of the operands (must be multiple of 4 for BCD digits)
) (
    input wire [DATA_WIDTH-1:0] a,    // First BCD operand (each 4-bit group is a BCD digit)
    input wire [DATA_WIDTH-1:0] b,    // Second BCD operand (each 4-bit group is a BCD digit)
    input wire cin,                   // Carry-in (decimal carry)
    output wire [DATA_WIDTH-1:0] sum, // BCD sum output (each 4-bit group is a BCD digit)
    output wire cout                  // Carry-out (decimal carry)
);

// Number of BCD digits (each digit is 4 bits)
// DATA_WIDTH must be divisible by 4
localparam NUM_BCD_DIGITS = DATA_WIDTH / 4;

// Internal carry signals between BCD digits
// digit_carry[i] is the carry entering BCD digit i
wire [NUM_BCD_DIGITS:0] digit_carry;
assign digit_carry[0] = cin;      // Input carry enters the first BCD digit
assign cout = digit_carry[NUM_BCD_DIGITS]; // Output carry exits the last BCD digit

// Generate BCD adder logic for each digit
// Each BCD digit is processed independently with carry propagation between digits
genvar i;
generate
    for (i = 0; i < NUM_BCD_DIGITS; i = i + 1) begin : bcd_digit_adder
        // Extract 4-bit BCD digits from the full-width operands
        // Each digit occupies 4 consecutive bits: bits [i*4+3 : i*4]
        wire [3:0] a_digit = a[(i*4)+3:(i*4)];  // BCD digit from operand a
        wire [3:0] b_digit = b[(i*4)+3:(i*4)];  // BCD digit from operand b

        // Binary sum of the current digit (5 bits to handle carry)
        // Perform binary addition: a_digit + b_digit + carry_in
        // Result can be 0-18 (with carry-in), so we need 5 bits
        wire [4:0] binary_sum = {1'b0, a_digit} + {1'b0, b_digit} + {4'b0000, digit_carry[i]};

        // BCD correction: if binary_sum >= 10, add 6 to correct to valid BCD range
        // This correction ensures the result is a valid BCD digit (0-9)
        // 
        // Why add 6?
        //   - Binary 10-15 are invalid BCD digits
        //   - Adding 6 skips these invalid values: 10+6=16, 11+6=17, ..., 15+6=21
        //   - In binary: 16 = 0x10, 17 = 0x11, ..., 21 = 0x15
        //   - The lower 4 bits become valid BCD (0-5), and bit 4 becomes the carry
        // 
        // Use explicit comparison with proper width casting to ensure correct synthesis
        // Check if binary_sum >= 10 by comparing with explicit constant
        // This ensures Verilator synthesizes the comparison correctly
        wire [4:0] binary_sum_5bit = binary_sum[4:0];
        wire needs_correction = (binary_sum_5bit >= 5'd10) ? 1'b1 : 1'b0;
        wire [4:0] correction_amount = needs_correction ? 5'd6 : 5'd0;
        wire [4:0] corrected_sum = binary_sum_5bit + correction_amount;

        // Output the corrected 4-bit BCD digit
        // Extract the lower 4 bits as the BCD digit result
        assign sum[(i*4)+3:(i*4)] = corrected_sum[3:0];

        // Carry out to next digit
        // The carry is bit 4 of the corrected sum (indicates sum >= 10)
        // Extract the carry bit explicitly and assign it to ensure proper synthesis
        // Use an intermediate wire to force Verilator to properly synthesize the bit extraction
        wire carry_bit = corrected_sum[4];
        assign digit_carry[i+1] = carry_bit;
    end
endgenerate

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_brent_kung.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off UNUSEDGENVAR */
/* verilator lint_off UNUSEDSIGNAL */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Brent-Kung Adder
 * 
 * This module implements a Brent-Kung prefix tree adder, which uses a two-phase
 * approach: forward tree (compute group prefixes) and reverse tree (distribute
 * prefixes to individual positions). This design minimizes wiring complexity
 * at the cost of increased logic depth compared to Kogge-Stone.
 * 
 * Algorithm:
 *   - Forward tree: Computes group generate/propagate signals with sparse connections
 *   - Reverse tree: Distributes computed prefixes back to individual positions
 *   - Two-phase approach reduces wiring but increases depth to 2*log2(n)
 * 
 * Brent-Kung Characteristics:
 *   - Logic Depth: 2*log2(n) - deeper than Kogge-Stone but with less wiring
 *   - Fanout: Low - minimal wiring complexity
 *   - Area: Moderate - less area than Kogge-Stone, more than ripple carry
 *   - Speed: Good - faster than ripple, slower than Kogge-Stone
 * 
 * Prefix Tree Structure:
 *   Forward Phase: Build up group prefixes (sparse connections)
 *   Reverse Phase: Distribute prefixes to all positions
 * 
 * Use case: Medium-to-large adders where balanced speed/area is desired and
 *           wiring complexity is a concern
 * 
 * @param DATA_WIDTH Width of input operands and sum output (must be power of 2, default: 32)
 */
module brent_kung_adder #(
    parameter DATA_WIDTH = 32    // Width of the operands
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow
);

    // Number of stages in the Brent-Kung prefix tree
    // Brent-Kung uses 2*log2(n) stages total: log2(n) forward + log2(n) reverse
    localparam STAGES = $clog2(DATA_WIDTH);

    // Generate and Propagate signals (initial values)
    wire [DATA_WIDTH-1:0] g_init;  // Generate: G[i] = a[i] & b[i]
    wire [DATA_WIDTH-1:0] p_init;  // Propagate: P[i] = a[i] ^ b[i]

    // Generate initial P and G values for each bit position
    // These are computed independently and in parallel
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : init_pg
            // Generate: carry is generated when both inputs are 1
            assign g_init[i] = a[i] & b[i];

            // Propagate: carry propagates when exactly one input is 1
            assign p_init[i] = a[i] ^ b[i];
        end
    endgenerate

    // Forward tree signals (Brent-Kung structure)
    // Forward tree computes group generate and propagate signals
    // This phase builds up prefixes for groups of increasing size
    wire [DATA_WIDTH-1:0] g_forward [STAGES:0];
    wire [DATA_WIDTH-1:0] p_forward [STAGES:0];

    // Initialize forward tree with initial P and G
    // Stage 0 represents individual bit positions
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : init_forward
            assign g_forward[0][i] = g_init[i];
            assign p_forward[0][i] = p_init[i];
        end
    endgenerate

    // Build the Brent-Kung forward tree
    // This is a binary tree where each level combines adjacent pairs
    // The forward tree uses sparse connections to reduce wiring complexity
    genvar stage, j;
    generate
        for (stage = 0; stage < STAGES; stage = stage + 1) begin : forward_stage
            // Step size doubles each stage (1, 2, 4, 8, ...)
            // Stage i connects positions that are 2^i apart
            localparam step = 1 << stage;

            for (j = 0; j < DATA_WIDTH; j = j + 1) begin : forward_bit
                if (j >= step) begin : combine
                    // Combine with the bit 'step' positions back
                    // This implements the prefix operator: (G_j, P_j) o (G_{j-step}, P_{j-step})
                    // 
                    // Update generate: G_new = G_j OR (P_j AND G_{j-step})
                    // Carry is generated at j OR (carry propagates through j AND generated before j-step)
                    assign g_forward[stage+1][j] = g_forward[stage][j] | (p_forward[stage][j] & g_forward[stage][j-step]);

                    // Update propagate: P_new = P_j AND P_{j-step}
                    // Carry propagates through both j and j-step
                    assign p_forward[stage+1][j] = p_forward[stage][j] & p_forward[stage][j-step];
                end
                else begin : pass_through
                    // Lower bits (j < step) pass through unchanged
                    // They don't have a left neighbor at distance 'step' yet
                    assign g_forward[stage+1][j] = g_forward[stage][j];
                    assign p_forward[stage+1][j] = p_forward[stage][j];
                end
            end
        end
    endgenerate

    // Reverse tree signals
    // Reverse tree distributes the computed prefixes back to individual positions
    // This phase ensures every bit position gets the correct prefix value
    wire [DATA_WIDTH-1:0] g_reverse [STAGES:0];
    wire [DATA_WIDTH-1:0] p_reverse [STAGES:0];

    // Initialize reverse tree with the final forward stage
    // The reverse tree starts from the forward tree's final stage
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : init_reverse
            assign g_reverse[STAGES][i] = g_forward[STAGES][i];
            assign p_reverse[STAGES][i] = p_forward[STAGES][i];
        end
    endgenerate

    // Build the Brent-Kung reverse tree
    // This distributes the computed group prefixes back to individual bit positions
    // The reverse tree works backwards (from STAGES-1 down to 0)
    generate
        for (stage = STAGES-1; stage >= 0; stage = stage - 1) begin : reverse_stage
            localparam step = 1 << stage;

            for (j = 0; j < DATA_WIDTH; j = j + 1) begin : reverse_bit
                if (j >= step) begin : distribute
                    // Distribute the prefix from the higher position
                    // For each position j, we get the prefix from j-step and combine it with local P/G
                    // This ensures every position gets the correct prefix value
                    assign g_reverse[stage][j] = g_reverse[stage+1][j] | (p_reverse[stage+1][j] & g_reverse[stage+1][j-step]);
                    assign p_reverse[stage][j] = p_reverse[stage+1][j] & p_reverse[stage+1][j-step];
                end
                else begin : copy_from_forward
                    // For positions that don't get updated in reverse tree
                    // Copy from forward tree (these positions already have correct values)
                    assign g_reverse[stage][j] = g_forward[stage][j];
                    assign p_reverse[stage][j] = p_forward[stage][j];
                end
            end
        end
    endgenerate

    // Generate the carries using the final reverse stage P and G values
    wire [DATA_WIDTH:0] carries;
    assign carries[0] = cin;  // Initial carry-in

    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : carry_gen
            // c_{i+1} = g_i | (p_i & c_i)
            assign carries[i+1] = g_reverse[0][i] | (p_reverse[0][i] & carries[i]);
        end
    endgenerate

    // Compute the sum bits
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : sum_gen
            assign sum[i] = p_init[i] ^ carries[i];  // sum = a ^ b ^ carry_in
        end
    endgenerate

    // Final carry-out
    assign cout = carries[DATA_WIDTH];

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on UNUSEDGENVAR */
/* verilator lint_on UNUSEDSIGNAL */
/* verilator lint_on GENUNNAMED */

db_brent_kung_hybrid.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off UNUSEDGENVAR */
/* verilator lint_off UNUSEDSIGNAL */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Brent-Kung Hybrid Adder
 * 
 * This module implements a Brent-Kung prefix tree adder with parameterized hybrid modes.
 * Brent-Kung uses a two-phase approach: forward tree (compute group prefixes) and
 * reverse tree (distribute prefixes to individual positions). This hybrid version
 * allows mixing different strategies to optimize for specific design goals.
 * 
 * Algorithm:
 *   - Forward tree: Computes group generate/propagate signals (sparse connections)
 *   - Reverse tree: Distributes computed prefixes back to individual positions
 *   - Hybrid modes allow switching strategies based on group size or design goals
 * 
 * Brent-Kung Characteristics:
 *   - Logic Depth: 2*log2(n) - deeper than Kogge-Stone but with less wiring
 *   - Fanout: Low - minimal wiring complexity
 *   - Area: Moderate - less area than Kogge-Stone, more than ripple carry
 *   - Speed: Good - faster than ripple, slower than Kogge-Stone
 * 
 * Hybrid Modes:
 *   - Mode 0 (Pure Brent-Kung): Standard Brent-Kung implementation
 *   - Mode 1 (Ripple Hybrid): Use ripple carry for small groups (step <= RIPPLE_THRESHOLD)
 *   - Mode 2 (Carry-Select Hybrid): Use carry-select for large groups (step >= SELECT_THRESHOLD)
 * 
 * Use case: Medium-to-large adders where balanced speed/area is desired
 * 
 * @param DATA_WIDTH Width of input operands and sum output (must be power of 2, default: 32)
 * @param HYBRID_MODE Hybrid mode: 0=Pure BK, 1=Ripple hybrid, 2=Carry-select hybrid (default: 0)
 * @param RIPPLE_THRESHOLD Switch to ripple carry for groups smaller than this (default: 4)
 * @param SELECT_THRESHOLD Switch to carry-select for groups larger than this (default: 8)
 */
module brent_kung_hybrid_adder #(
    parameter DATA_WIDTH = 32,    // Width of the operands
    parameter HYBRID_MODE = 0,    // 0: Pure Brent-Kung, 1: Ripple hybrid, 2: Carry-select hybrid
    parameter RIPPLE_THRESHOLD = 4,  // Switch to ripple carry for groups smaller than this
    parameter SELECT_THRESHOLD = 8   // Switch to carry-select for groups larger than this
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow
);

    // Number of stages in the Brent-Kung prefix tree
    // Brent-Kung uses 2*log2(n) stages total: log2(n) forward + log2(n) reverse
    localparam STAGES = $clog2(DATA_WIDTH);

    // Generate and Propagate signals (initial values)
    wire [DATA_WIDTH-1:0] g_init;  // Generate: G[i] = a[i] & b[i]
    wire [DATA_WIDTH-1:0] p_init;  // Propagate: P[i] = a[i] ^ b[i]

    // Generate initial P and G values for each bit position
    // These are computed independently and in parallel
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : init_pg
            // Generate: carry is generated when both inputs are 1
            assign g_init[i] = a[i] & b[i];

            // Propagate: carry propagates when exactly one input is 1
            assign p_init[i] = a[i] ^ b[i];
        end
    endgenerate

    // Forward tree signals (Brent-Kung hybrid structure)
    // Forward tree computes group generate and propagate signals
    // This phase builds up prefixes for groups of increasing size
    wire [DATA_WIDTH-1:0] g_forward [STAGES:0];
    wire [DATA_WIDTH-1:0] p_forward [STAGES:0];

    // Initialize forward tree with initial P and G
    // Stage 0 represents individual bit positions
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : init_forward
            assign g_forward[0][i] = g_init[i];
            assign p_forward[0][i] = p_init[i];
        end
    endgenerate

    // Build the Brent-Kung hybrid forward tree
    // This implements different strategies based on HYBRID_MODE and thresholds
    // The forward tree computes prefixes for groups, but with sparse connections
    genvar stage, j;
    generate
        for (stage = 0; stage < STAGES; stage = stage + 1) begin : forward_stage
            // Step size for this stage: doubles each stage (1, 2, 4, 8, ...)
            localparam step = 1 << stage;

            for (j = 0; j < DATA_WIDTH; j = j + 1) begin : forward_bit
                if (j >= step) begin : combine
                    // Different hybrid strategies based on mode and thresholds
                    // This allows optimizing different parts of the tree differently
                    if (HYBRID_MODE == 0) begin : pure_brent_kung
                        // Pure Brent-Kung: Standard prefix computation
                        // Sparse connections: only connect at specific positions
                        // Update generate: G_new = G_j OR (P_j AND G_{j-step})
                        assign g_forward[stage+1][j] = g_forward[stage][j] | (p_forward[stage][j] & g_forward[stage][j-step]);

                        // Update propagate: P_new = P_j AND P_{j-step}
                        assign p_forward[stage+1][j] = p_forward[stage][j] & p_forward[stage][j-step];
                    end
                    else if (HYBRID_MODE == 1 && step <= RIPPLE_THRESHOLD) begin : ripple_hybrid
                        // For small steps, use ripple-like carry propagation
                        // This reduces logic depth for small groups
                        // Same computation as pure BK, but applied only to small groups
                        assign g_forward[stage+1][j] = g_forward[stage][j] | (p_forward[stage][j] & g_forward[stage][j-step]);
                        assign p_forward[stage+1][j] = p_forward[stage][j] & p_forward[stage][j-step];
                    end
                    else if (HYBRID_MODE == 2 && step >= SELECT_THRESHOLD) begin : select_hybrid
                        // For large steps, use carry-select like behavior
                        // Pre-compute both carry possibilities (though selection logic is simplified here)
                        wire g_select_0 = g_forward[stage][j] | (p_forward[stage][j] & g_forward[stage][j-step]);
                        wire p_select_0 = p_forward[stage][j] & p_forward[stage][j-step];
                        wire g_select_1 = 1'b1;  // Assume carry-in = 1 (always generate)
                        wire p_select_1 = 1'b0;  // Blocked when carry-in = 1 (no propagation)

                        // Select based on carry-in from previous stage
                        // Note: This is a simplified version - full carry-select would compute both paths
                        assign g_forward[stage+1][j] = g_select_0;
                        assign p_forward[stage+1][j] = p_select_0;
                    end
                    else begin : standard_hybrid
                        // Default Brent-Kung behavior for hybrid modes
                        // Used when hybrid conditions don't apply
                        assign g_forward[stage+1][j] = g_forward[stage][j] | (p_forward[stage][j] & g_forward[stage][j-step]);
                        assign p_forward[stage+1][j] = p_forward[stage][j] & p_forward[stage][j-step];
                    end
                end
                else begin : pass_through
                    // Lower bits (j < step) pass through unchanged
                    // They don't have a left neighbor at distance 'step' yet
                    assign g_forward[stage+1][j] = g_forward[stage][j];
                    assign p_forward[stage+1][j] = p_forward[stage][j];
                end
            end
        end
    endgenerate

    // Reverse tree signals
    // Reverse tree distributes the computed prefixes back to individual positions
    // This phase ensures every bit position gets the correct prefix value
    wire [DATA_WIDTH-1:0] g_reverse [STAGES:0];
    wire [DATA_WIDTH-1:0] p_reverse [STAGES:0];

    // Initialize reverse tree with the final forward stage
    // The reverse tree starts from the forward tree's final stage
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : init_reverse
            assign g_reverse[STAGES][i] = g_forward[STAGES][i];
            assign p_reverse[STAGES][i] = p_forward[STAGES][i];
        end
    endgenerate

    // Build the Brent-Kung hybrid reverse tree
    // This distributes the computed group prefixes back to individual bit positions
    // The reverse tree works backwards (from STAGES-1 down to 0)
    generate
        for (stage = STAGES-1; stage >= 0; stage = stage - 1) begin : reverse_stage
            localparam step = 1 << stage;

            for (j = 0; j < DATA_WIDTH; j = j + 1) begin : reverse_bit
                if (j >= step) begin : distribute
                    // Distribute the prefix from the higher position
                    // For each position j, we get the prefix from j-step and combine it with local P/G
                    // This ensures every position gets the correct prefix value
                    if (HYBRID_MODE == 0) begin : pure_reverse
                        // Pure Brent-Kung reverse: standard prefix distribution
                        assign g_reverse[stage][j] = g_reverse[stage+1][j] | (p_reverse[stage+1][j] & g_reverse[stage+1][j-step]);
                        assign p_reverse[stage][j] = p_reverse[stage+1][j] & p_reverse[stage+1][j-step];
                    end
                    else if (HYBRID_MODE == 1 && step <= RIPPLE_THRESHOLD) begin : ripple_reverse
                        // Simplified reverse for small steps in ripple hybrid mode
                        // Same computation as pure BK
                        assign g_reverse[stage][j] = g_reverse[stage+1][j] | (p_reverse[stage+1][j] & g_reverse[stage+1][j-step]);
                        assign p_reverse[stage][j] = p_reverse[stage+1][j] & p_reverse[stage+1][j-step];
                    end
                    else begin : standard_reverse
                        // Default reverse behavior for hybrid modes
                        assign g_reverse[stage][j] = g_reverse[stage+1][j] | (p_reverse[stage+1][j] & g_reverse[stage+1][j-step]);
                        assign p_reverse[stage][j] = p_reverse[stage+1][j] & p_reverse[stage+1][j-step];
                    end
                end
                else begin : copy_from_forward
                    // For positions that don't get updated in reverse tree
                    // Copy from forward tree (these positions already have correct values)
                    assign g_reverse[stage][j] = g_forward[stage][j];
                    assign p_reverse[stage][j] = p_forward[stage][j];
                end
            end
        end
    endgenerate

    // Generate the carries using the final reverse stage P and G values
    wire [DATA_WIDTH:0] carries;
    assign carries[0] = cin;  // Initial carry-in

    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : carry_gen
            // c_{i+1} = g_i | (p_i & c_i)
            assign carries[i+1] = g_reverse[0][i] | (p_reverse[0][i] & carries[i]);
        end
    endgenerate

    // Compute the sum bits
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : sum_gen
            assign sum[i] = p_init[i] ^ carries[i];  // sum = a ^ b ^ carry_in
        end
    endgenerate

    // Final carry-out
    assign cout = carries[DATA_WIDTH];

endmodule

