/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Carry-Chain Adder
 * 
 * This module implements a carry-chain adder, which is essentially a ripple carry
 * adder where carries propagate sequentially through a chain of full adders. This
 * is the simplest adder implementation and serves as a baseline for comparison.
 * 
 * Algorithm:
 *   - Each bit position uses a full adder
 *   - Carries propagate sequentially from LSB to MSB
 *   - Full adder computes: sum = a XOR b XOR carry_in
 *   - Full adder computes: carry_out = (a AND b) OR ((a OR b) AND carry_in)
 * 
 * Characteristics:
 *   - Area: Minimal - only full adders, no extra logic
 *   - Delay: O(n) - worst case delay grows linearly with width
 *   - Power: Low - minimal switching activity
 *   - Use case: Small adders, area-constrained designs, or when delay is not critical
 * 
 * Note: This is functionally identical to a ripple carry adder. The name "chain"
 * emphasizes the sequential carry propagation through the chain of adders.
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 */
module carry_chain_adder #(
    parameter DATA_WIDTH = 32    // Width of the operands
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in (typically 0 for addition, 1 for increment)
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow when DATA_WIDTH bits insufficient
);

    // Internal carry chain signals - each carry propagates to the next bit
    // Size is DATA_WIDTH+1 to accommodate carry_chain[0] (cin) through carry_chain[DATA_WIDTH] (cout)
    wire [DATA_WIDTH:0] carry_chain;
    assign carry_chain[0] = cin;      // Input carry starts the chain
    assign cout = carry_chain[DATA_WIDTH]; // Final carry from the chain

    // Generate full adders for each bit position in the carry chain
    // Each full adder computes the sum and carry-out for one bit position
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : carry_chain_stage
            // Each stage in the carry chain:
            // - Takes carry_in from previous stage
            // - Produces sum bit and carry_out to next stage
            wire carry_in = carry_chain[i];  // Carry entering this bit position
            wire carry_out;                  // Carry leaving this bit position

            // Full adder logic for this bit position
            // Sum calculation: XOR of all three inputs
            // sum[i] = a[i] XOR b[i] XOR carry_in
            // This implements: sum = a + b + carry_in (mod 2)
            assign sum[i] = a[i] ^ b[i] ^ carry_in;

            // Carry-out calculation: optimized form of the standard full adder equation
            // carry_out = (a[i] & b[i]) | ((a[i] | b[i]) & carry_in)
            //   - First term: carry generated when both a[i] and b[i] are 1
            //   - Second term: carry propagated when at least one of a[i] or b[i] is 1 AND carry_in is 1
            // This carry_out becomes carry_chain[i+1] for the next stage
            assign carry_out = (a[i] & b[i]) | ((a[i] | b[i]) & carry_in);
            assign carry_chain[i+1] = carry_out;
        end
    endgenerate

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_carry_completion_sensing.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Carry Completion Sensing Adder (CCSA)
 * 
 * This module implements a carry completion sensing adder that detects when
 * the addition operation is complete. This is useful in asynchronous circuits
 * where operations complete at variable times, or in systems that need to know
 * when computation is finished.
 * 
 * Algorithm:
 *   - Uses ripple carry adder as the base
 *   - Monitors completion of each bit position
 *   - Groups bits into sensing windows for hierarchical completion detection
 *   - Outputs a completion signal when all bits are stable
 * 
 * Completion Sensing:
 *   - Each bit position has a completion signal indicating when its output is stable
 *   - Bits are grouped into sensing windows
 *   - Group completion = AND of all bit completions in the group
 *   - Global completion = AND of all group completions
 * 
 * Characteristics:
 *   - Area: Moderate - ripple carry plus completion sensing logic
 *   - Delay: O(n) - same as ripple carry, but with completion detection
 *   - Power: Moderate - completion sensing adds some overhead
 *   - Use case: Asynchronous circuits, self-timed systems, or when completion
 *               detection is needed
 * 
 * Note: This implementation uses simplified completion detection. A full
 * implementation would use timing-based sensing to detect when signals stabilize.
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 * @param SENSING_WINDOW Size of sensing groups for completion detection (default: 4)
 */
module carry_completion_sensing_adder #(
    parameter DATA_WIDTH = 32,      // Width of the operands
    parameter SENSING_WINDOW = 4    // Size of sensing groups for completion detection
) (
    input wire [DATA_WIDTH-1:0] a,      // First operand
    input wire [DATA_WIDTH-1:0] b,      // Second operand
    input wire cin,                     // Carry-in
    output wire [DATA_WIDTH-1:0] sum,   // Sum output: a + b + cin
    output wire cout,                   // Carry-out: indicates overflow
    output wire completion              // Completion signal - high when addition is complete
);

    // Internal carry signals between full adders
    // Size is DATA_WIDTH+1 to accommodate carry[0] (cin) through carry[DATA_WIDTH] (cout)
    wire [DATA_WIDTH:0] carry;
    assign carry[0] = cin;      // Input carry starts the chain
    assign cout = carry[DATA_WIDTH]; // Final carry from the chain

    // Completion signals for each bit position
    // bit_completion[i] indicates when bit position i has completed computation
    wire [DATA_WIDTH-1:0] bit_completion;

    // Calculate number of sensing groups
    // Bits are grouped into windows for hierarchical completion detection
    localparam NUM_GROUPS = (DATA_WIDTH + SENSING_WINDOW - 1) / SENSING_WINDOW;

    // Group completion signals
    // group_completion[i] indicates when all bits in group i have completed
    wire [NUM_GROUPS-1:0] group_completion;

    // Generate full adders with completion sensing for each bit position
    // Each full adder computes sum and carry, plus completion detection
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : full_adder_with_sensing
            // Full adder logic
            // Sum calculation: XOR of all three inputs
            wire sum_bit = a[i] ^ b[i] ^ carry[i];

            // Carry-out calculation: generate OR propagate
            wire carry_out = (a[i] & b[i]) | ((a[i] | b[i]) & carry[i]);

            // Output sum and carry
            assign sum[i] = sum_bit;
            assign carry[i+1] = carry_out;

            // Completion sensing logic for each bit
            // A bit is considered complete when its carry output is stable
            // For CCSA, we use a simple completion detection based on carry stability
            // In practice, this would involve more sophisticated timing-based sensing
            // (e.g., using delay elements, Muller C-elements, or transition detection)
            // For simulation purposes, assume immediate completion.
            // (Avoid an empty-sensitivity always block that Verilator warns about.)
            // 
            // Note: A full implementation would detect when signals have stabilized
            // after all transitions have completed, enabling true asynchronous operation
            assign bit_completion[i] = 1'b1;
        end
    endgenerate

    // Group completion logic - each group is complete when all bits in the group are complete
    // This provides hierarchical completion detection for better scalability
    generate
        for (i = 0; i < NUM_GROUPS; i = i + 1) begin : sensing_groups
            // Calculate the range of bits in this group
            localparam GROUP_START = i * SENSING_WINDOW;
            localparam GROUP_END = (GROUP_START + SENSING_WINDOW > DATA_WIDTH) ?
                                   DATA_WIDTH - 1 : GROUP_START + SENSING_WINDOW - 1;

            // All bits in this group must be complete for the group to be complete
            // Extract completion signals for bits in this group
            wire [GROUP_END-GROUP_START:0] group_bits_complete;
            assign group_bits_complete = bit_completion[GROUP_END:GROUP_START];

            // Group completion is the AND of all bit completions in the group
            // A group is complete only when ALL bits in the group have completed
            assign group_completion[i] = &group_bits_complete;
        end
    endgenerate

    // Global completion - all groups must be complete
    // The addition is complete only when ALL groups have completed
    // This provides a single completion signal for the entire adder
    assign completion = &group_completion;

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_carry_generate_propagate.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Carry-Generate/Propagate Adder
 * 
 * This module implements a carry-generate/propagate adder that uses hierarchical
 * group-level generate and propagate signals. Unlike standard CLA, this uses OR-based
 * propagate (P = a OR b) instead of XOR-based propagate, which simplifies some logic
 * but requires different carry computation.
 * 
 * Algorithm:
 *   - Operands divided into groups of GROUP_SIZE bits
 *   - For each bit: G[i] = a[i] & b[i], P[i] = a[i] | b[i]
 *   - Compute hierarchical group-level G and P signals
 *   - Use group signals to compute carries between groups
 *   - Compute individual bit carries within groups
 * 
 * Generate and Propagate Definition:
 *   - Generate (G): G[i] = a[i] & b[i] (carry generated when both inputs are 1)
 *   - Propagate (P): P[i] = a[i] | b[i] (carry propagates when at least one input is 1)
 *   - Note: This uses OR-based propagate, different from XOR-based propagate in standard CLA
 * 
 * Characteristics:
 *   - Area: Moderate - hierarchical group logic
 *   - Delay: O(n/GROUP_SIZE) - faster than ripple carry
 *   - Power: Moderate - group-level computation
 *   - Use case: Medium-width adders where hierarchical grouping is beneficial
 * 
 * Difference from Standard CLA:
 *   - Standard CLA: P[i] = a[i] XOR b[i] (exactly one input is 1)
 *   - This adder: P[i] = a[i] OR b[i] (at least one input is 1)
 *   - OR-based propagate simplifies some logic but requires different carry equations
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 * @param GROUP_SIZE Size of each carry-generate/propagate group (default: 4)
 */
module carry_generate_propagate_adder #(
    parameter DATA_WIDTH = 32,    // Width of the operands
    parameter GROUP_SIZE = 4      // Size of each carry-generate/propagate group
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow
);

    // Calculate the number of groups needed
    // Ceiling division ensures we have enough groups even if DATA_WIDTH is not a multiple of GROUP_SIZE
    localparam NUM_GROUPS = (DATA_WIDTH + GROUP_SIZE - 1) / GROUP_SIZE;

    // Generate and Propagate signals for each bit
    // These use OR-based propagate (different from standard CLA which uses XOR)
    wire [DATA_WIDTH-1:0] g;          // Generate: carry is generated at this bit
    wire [DATA_WIDTH-1:0] p;          // Propagate: carry can propagate through this bit

    // Carry signals between groups
    // group_carry[i] is the carry entering group i
    wire [NUM_GROUPS:0] group_carry;
    assign group_carry[0] = cin;      // Input carry enters the first group
    assign cout = group_carry[NUM_GROUPS]; // Output carry exits the last group

    // Internal carry signals for each bit
    // These are computed using group carries and bit-level G/P signals
    wire [DATA_WIDTH:0] carry;
    assign carry[0] = cin;  // Input carry enters the first bit

    // Generate P and G signals for each bit position
    // These are computed independently and in parallel
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : pg_bit_logic
            // Generate: carry is generated when both inputs are 1
            // G[i] = 1 means: regardless of carry-in, this bit will produce carry-out
            assign g[i] = a[i] & b[i];

            // Propagate: carry can propagate when at least one input is 1
            // P[i] = 1 means: if carry-in is 1, carry-out will be 1
            // Note: This uses OR (not XOR) - different from standard CLA
            assign p[i] = a[i] | b[i];
        end
    endgenerate

    // For each group, implement the carry generate/propagate logic
    generate
        for (i = 0; i < NUM_GROUPS; i = i + 1) begin : cgpa_groups
            // Calculate the width of this group (handle the case where the last group might be smaller)
            localparam CURRENT_GROUP_SIZE = ((i+1)*GROUP_SIZE <= DATA_WIDTH) ?
                                            GROUP_SIZE :
                                            DATA_WIDTH - (i*GROUP_SIZE);

            // Calculate start and end indices for this group
            localparam START_IDX = i * GROUP_SIZE;
            localparam END_IDX = START_IDX + CURRENT_GROUP_SIZE - 1;

            // Extract group signals
            wire [CURRENT_GROUP_SIZE-1:0] group_p = p[END_IDX:START_IDX];
            wire [CURRENT_GROUP_SIZE-1:0] group_g = g[END_IDX:START_IDX];

            // Group-level generate and propagate signals
            wire group_G, group_P;

            // Compute group-level generate and propagate using carry-generate/propagate logic
            if (CURRENT_GROUP_SIZE == 1) begin : single_bit_group
                assign group_G = group_g[0];
                assign group_P = group_p[0];
            end else begin : multi_bit_group
                // For multi-bit groups, compute hierarchical G and P
                // Group_G = g[n-1] | (p[n-1] & (g[n-2] | (p[n-2] & (...))))
                // Group_P = p[n-1] & p[n-2] & ... & p[0]
                wire [CURRENT_GROUP_SIZE-1:0] level_G;
                wire [CURRENT_GROUP_SIZE-1:0] level_P;

                genvar j, k;
                for (j = 0; j < CURRENT_GROUP_SIZE; j = j + 1) begin : level_compute
                    if (j == 0) begin
                        assign level_G[j] = group_g[j];
                        assign level_P[j] = group_p[j];
                    end else begin
                        assign level_G[j] = group_g[j] | (group_p[j] & level_G[j-1]);
                        assign level_P[j] = group_p[j] & level_P[j-1];
                    end
                end

                assign group_G = level_G[CURRENT_GROUP_SIZE-1];
                assign group_P = level_P[CURRENT_GROUP_SIZE-1];
            end

            // Compute the carry-out for this group
            assign group_carry[i+1] = group_G | (group_P & group_carry[i]);
        end
    endgenerate

    // Compute carries for individual bits using the group carries
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : bit_carry_compute
            // Find which group this bit belongs to
            localparam GROUP_IDX = i / GROUP_SIZE;
            localparam BIT_IN_GROUP = i % GROUP_SIZE;

            // The carry into this bit comes from the group carry, plus any carries generated within the group
            if (BIT_IN_GROUP == 0) begin : first_bit_in_group
                // First bit in group gets the group carry directly
                assign carry[i+1] = g[i] | (p[i] & group_carry[GROUP_IDX]);
            end else begin : other_bits_in_group
                // Other bits get carries computed from previous bits in the group
                wire [BIT_IN_GROUP:0] subgroup_carry;
                assign subgroup_carry[0] = group_carry[GROUP_IDX];

                genvar k;
                for (k = 0; k < BIT_IN_GROUP; k = k + 1) begin : subgroup_carry_calc
                    localparam bit_idx = GROUP_IDX * GROUP_SIZE + k;
                    assign subgroup_carry[k+1] = g[bit_idx] | (p[bit_idx] & subgroup_carry[k]);
                end

                assign carry[i+1] = g[i] | (p[i] & subgroup_carry[BIT_IN_GROUP]);
            end
        end
    endgenerate

    // Compute the sum
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : sum_logic
            assign sum[i] = a[i] ^ b[i] ^ carry[i]; // XOR all three inputs for final sum
        end
    endgenerate

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_carry_lookahead.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Carry Lookahead Adder (CLA)
 * 
 * This module implements a grouped carry lookahead adder that computes carries
 * in parallel within groups, significantly reducing delay compared to ripple carry.
 * 
 * Algorithm:
 *   - The adder is divided into groups of GROUP_SIZE bits
 *   - For each bit, compute Generate (G) and Propagate (P) signals:
 *     * G[i] = a[i] AND b[i]  (carry is generated at this bit)
 *     * P[i] = a[i] XOR b[i]  (carry propagates through this bit)
 *   - Within each group, carries are computed in parallel using:
 *     * c[i+1] = G[i] OR (P[i] AND c[i])
 *   - Group carries propagate sequentially between groups
 * 
 * Characteristics:
 *   - Area: O(n) - moderate increase over ripple carry
 *   - Delay: O(n/GROUP_SIZE) - much faster than ripple for large widths
 *   - Power: Moderate - more switching than ripple carry
 *   - Use case: Medium-width adders where speed is important but full prefix tree is overkill
 * 
 * Trade-offs:
 *   - Larger GROUP_SIZE reduces delay but increases area and fanout
 *   - Typical GROUP_SIZE values: 4 (balanced), 8 (faster), 2 (smaller area)
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 * @param GROUP_SIZE Size of each carry-lookahead group (default: 4)
 */
module carry_lookahead_adder #(
    parameter DATA_WIDTH = 32,    // Width of the operands
    parameter GROUP_SIZE = 4      // Size of each carry-lookahead group
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow
);

    // Calculate the number of groups needed
    // Ceiling division: (DATA_WIDTH + GROUP_SIZE - 1) / GROUP_SIZE
    // Handles cases where DATA_WIDTH is not a multiple of GROUP_SIZE
    localparam NUM_GROUPS = (DATA_WIDTH + GROUP_SIZE - 1) / GROUP_SIZE;

    // Generate and Propagate signals for each bit
    // These signals form the foundation of carry lookahead computation
    wire [DATA_WIDTH-1:0] g;          // Generate: G[i] = 1 means a carry is generated at bit i
    wire [DATA_WIDTH-1:0] p;          // Propagate: P[i] = 1 means a carry propagates through bit i

    // Carry signals between groups
    // group_carry[i] is the carry entering group i
    wire [NUM_GROUPS:0] group_carry;
    assign group_carry[0] = cin;      // Input carry enters the first group
    assign cout = group_carry[NUM_GROUPS]; // Output carry exits the last group

    // Generate P and G signals for each bit position
    // These are computed independently and in parallel for all bits
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : pg_bit_logic
            // Generate signal: carry is generated when both inputs are 1
            // G[i] = 1 means: regardless of carry-in, this bit will produce carry-out
            assign g[i] = a[i] & b[i];

            // Propagate signal: carry propagates when exactly one input is 1
            // P[i] = 1 means: if carry-in is 1, carry-out will be 1; if carry-in is 0, carry-out will be 0
            // Note: Using XOR (not OR) ensures proper addition semantics
            assign p[i] = a[i] ^ b[i];
        end
    endgenerate

    // Carry signals for each bit position (computed within groups)
    wire [DATA_WIDTH-1:0] c_internal;

    // For each group, implement the carry lookahead logic
    // Within each group, all carries are computed in parallel
    generate
        for (i = 0; i < NUM_GROUPS; i = i + 1) begin : cla_groups
            // Calculate the width of this group
            // The last group may be smaller if DATA_WIDTH is not a multiple of GROUP_SIZE
            localparam CURRENT_GROUP_SIZE = ((i+1)*GROUP_SIZE <= DATA_WIDTH) ? 
                                            GROUP_SIZE : 
                                            DATA_WIDTH - (i*GROUP_SIZE);

            // Calculate start and end indices for this group
            // Used to extract the relevant bits from the full-width P and G signals
            localparam START_IDX = i * GROUP_SIZE;
            localparam END_IDX = START_IDX + CURRENT_GROUP_SIZE - 1;

            // Inline CLA group logic
            // Carries within this group, computed in parallel
            wire [CURRENT_GROUP_SIZE:0] group_c_internal;

            // Extract P and G signals for this group
            wire [CURRENT_GROUP_SIZE-1:0] group_p = p[END_IDX:START_IDX];
            wire [CURRENT_GROUP_SIZE-1:0] group_g = g[END_IDX:START_IDX];

            // Initialize: carry entering this group comes from previous group
            assign group_c_internal[0] = group_carry[i];

            // Output: carry leaving this group goes to next group
            assign group_carry[i+1] = group_c_internal[CURRENT_GROUP_SIZE];

            // Calculate all carries within this group using CLA equations
            // All carries in the group are computed in parallel (not sequentially)
            genvar j;
            for (j = 0; j < CURRENT_GROUP_SIZE; j = j + 1) begin : cla_carry_calc
                // Export carry for bit position START_IDX+j
                assign c_internal[START_IDX + j] = group_c_internal[j];

                // Carry-out calculation using lookahead formula:
                // c[j+1] = G[j] OR (P[j] AND c[j])
                // This computes: carry is generated at j OR (carry propagates through j AND carry exists at j)
                assign group_c_internal[j+1] = group_g[j] | (group_p[j] & group_c_internal[j]);
            end
        end
    endgenerate

    // Compute the sum bits
    // Sum = P XOR carry_in (since P = a XOR b, and sum = a XOR b XOR carry_in)
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : sum_logic
            // Final sum: XOR propagate signal with carry-in
            // This is equivalent to: sum[i] = a[i] XOR b[i] XOR c_internal[i]
            assign sum[i] = p[i] ^ c_internal[i];
        end
    endgenerate

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

