/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Carry Lookahead BCD Adder
 * 
 * This module implements a BCD adder with carry lookahead (CLA) to speed up
 * decimal addition. It combines BCD digit addition with CLA to reduce the
 * delay compared to a simple ripple-carry BCD adder.
 * 
 * Algorithm:
 *   - Each BCD digit is 4 bits (represents 0-9)
 *   - BCD digits are grouped for carry lookahead
 *   - Within each group, carries are computed in parallel using CLA
 *   - Each digit performs binary addition + BCD correction
 *   - Generate/Propagate signals computed at digit level (not bit level)
 * 
 * BCD Addition with CLA:
 *   - Binary sum: binary_sum = a_digit + b_digit + carry_in
 *   - BCD correction: if binary_sum >= 10, add 6
 *   - Generate: digit generates carry if (a + b) >= 10 (without carry-in)
 *   - Propagate: digit propagates carry if (a + b) >= 9 (would be >= 10 with carry-in)
 * 
 * Characteristics:
 *   - Area: Moderate - BCD adders plus CLA logic per group
 *   - Delay: O(n/GROUP_SIZE) - faster than ripple-carry BCD
 *   - Power: Moderate - CLA adds some overhead
 *   - Use case: High-speed decimal arithmetic, financial calculations
 * 
 * Trade-offs:
 *   - Larger GROUP_SIZE reduces delay but increases area
 *   - Typical GROUP_SIZE: 2-4 BCD digits
 * 
 * Note: DATA_WIDTH must be a multiple of 4 (each BCD digit is 4 bits)
 * 
 * @param DATA_WIDTH Width of input operands and sum output (must be multiple of 4, default: 32)
 * @param GROUP_SIZE Number of BCD digits per carry-lookahead group (default: 2)
 */
module carry_lookahead_bcd_adder #(
    parameter DATA_WIDTH = 32,    // Width of the operands (must be multiple of 4 for BCD digits)
    parameter GROUP_SIZE = 2      // Number of BCD digits per carry-lookahead group
) (
    input wire [DATA_WIDTH-1:0] a,    // First BCD operand (each 4-bit group is a BCD digit)
    input wire [DATA_WIDTH-1:0] b,    // Second BCD operand (each 4-bit group is a BCD digit)
    input wire cin,                   // Carry-in (decimal carry)
    output wire [DATA_WIDTH-1:0] sum, // BCD sum output (each 4-bit group is a BCD digit)
    output wire cout                  // Carry-out (decimal carry)
);

    // Ensure DATA_WIDTH is multiple of 4 (BCD digit size)
    localparam BCD_DIGIT_WIDTH = 4;
    localparam NUM_BCD_DIGITS = DATA_WIDTH / BCD_DIGIT_WIDTH;
    localparam NUM_GROUPS = (NUM_BCD_DIGITS + GROUP_SIZE - 1) / GROUP_SIZE;

    // BCD digit signals
    // Arrays to hold individual BCD digits extracted from operands
    wire [3:0] a_digits [0:NUM_BCD_DIGITS-1];
    wire [3:0] b_digits [0:NUM_BCD_DIGITS-1];
    wire [3:0] sum_digits [0:NUM_BCD_DIGITS-1];

    // Group carry signals for CLA logic
    // group_carry[i] is the decimal carry entering group i
    wire [NUM_GROUPS:0] group_carry;
    assign group_carry[0] = cin;      // Input carry enters the first group
    // Final carry-out is the carry out of the last group
    assign cout = group_carry[NUM_GROUPS];

    // Extract BCD digits from input operands
    // Each 4-bit group represents one BCD digit (0-9)
    genvar i, j;
    generate
        for (i = 0; i < NUM_BCD_DIGITS; i = i + 1) begin : extract_digits
            // Extract 4-bit BCD digit from operand a
            assign a_digits[i] = a[i*BCD_DIGIT_WIDTH +: BCD_DIGIT_WIDTH];
            // Extract 4-bit BCD digit from operand b
            assign b_digits[i] = b[i*BCD_DIGIT_WIDTH +: BCD_DIGIT_WIDTH];
            // Assign computed BCD digit to output
            assign sum[i*BCD_DIGIT_WIDTH +: BCD_DIGIT_WIDTH] = sum_digits[i];
        end
    endgenerate

    // Generate and Propagate signals for each BCD digit (for CLA)
    // These are computed at the digit level (not bit level) for BCD arithmetic
    wire [NUM_BCD_DIGITS-1:0] digit_g;  // Generate: decimal carry is generated at this digit
    wire [NUM_BCD_DIGITS-1:0] digit_p;  // Propagate: decimal carry is propagated through this digit

    // Process each BCD digit group with carry lookahead logic
    // Within each group, carries are computed in parallel
    generate
        for (i = 0; i < NUM_GROUPS; i = i + 1) begin : cla_groups
            // Calculate the number of digits in this group
            // The last group may be smaller if NUM_BCD_DIGITS is not a multiple of GROUP_SIZE
            localparam CURRENT_GROUP_SIZE = ((i+1)*GROUP_SIZE <= NUM_BCD_DIGITS) ?
                                           GROUP_SIZE :
                                           NUM_BCD_DIGITS - (i*GROUP_SIZE);

            // Calculate start and end digit indices for this group
            localparam START_DIGIT = i * GROUP_SIZE;
            localparam END_DIGIT = START_DIGIT + CURRENT_GROUP_SIZE - 1;

            // Group-level carry lookahead signals
            // Carries within this group, computed in parallel using CLA
            wire [CURRENT_GROUP_SIZE:0] group_decimal_carry;
            assign group_decimal_carry[0] = group_carry[i];  // Carry entering this group
            assign group_carry[i+1] = group_decimal_carry[CURRENT_GROUP_SIZE];  // Carry leaving this group

            // Process each BCD digit in the group
            for (j = 0; j < CURRENT_GROUP_SIZE; j = j + 1) begin : bcd_digits
                localparam DIGIT_IDX = START_DIGIT + j;

                // BCD digit addition logic
                // Use the group's carry (CLA-computed) as the carry-in for this digit.
                // Previously this incorrectly used ripple `decimal_carry[DIGIT_IDX]`, which was not tied to CLA.
                wire carry_in = group_decimal_carry[j];  // Carry entering this BCD digit

                // Binary addition: a_digit + b_digit + carry_in
                // Result can be 0-18 (with carry-in), so we need 5 bits
                wire [4:0] binary_sum = a_digits[DIGIT_IDX] + b_digits[DIGIT_IDX] + carry_in;

                // BCD correction: if binary_sum >= 10, add 6 to correct to valid BCD range
                wire invalid_bcd = (binary_sum >= 5'd10);
                wire [3:0] corrected_sum = invalid_bcd ? (binary_sum + 4'd6) : binary_sum[3:0];
                wire digit_cout = invalid_bcd;  // Carry out from this digit

                // Output the corrected 4-bit BCD digit
                assign sum_digits[DIGIT_IDX] = corrected_sum;

                // Generate and Propagate signals for CLA
                // These are computed at the digit level for BCD arithmetic
                // 
                // Generate: A digit generates carry if it produces invalid BCD (>= 10) without carry-in
                // This means: a + b >= 10 (carry is generated regardless of carry-in)
                assign digit_g[DIGIT_IDX] = (a_digits[DIGIT_IDX] + b_digits[DIGIT_IDX] >= 5'd10);

                // Propagate: A digit propagates carry if it would produce invalid BCD when carry-in = 1
                // This means: a + b >= 9 (with carry-in=1, it becomes >= 10)
                assign digit_p[DIGIT_IDX] = (a_digits[DIGIT_IDX] + b_digits[DIGIT_IDX] >= 5'd9);

                // For CLA groups, use simplified logic
                // Carry-out from this digit: generate OR (propagate AND carry-in)
                // This is the standard CLA formula applied at the digit level
                assign group_decimal_carry[j+1] = (group_decimal_carry[j] & digit_p[DIGIT_IDX]) | digit_g[DIGIT_IDX];
            end
        end
    endgenerate

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_carry_save.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Carry-Save Adder (CSA)
 * 
 * This module implements a carry-save adder, which is used in multi-operand addition
 * (e.g., in multipliers). Unlike regular adders, CSA does NOT propagate carries between
 * bit positions. Instead, it saves carries for later processing, converting three
 * operands (a, b, cin) into two outputs (sum, cout).
 * 
 * Algorithm:
 *   - Each bit position uses a full adder independently
 *   - No carry propagation between bits - all bits compute in parallel
 *   - Converts three operands to two: (a, b, cin) -> (sum, cout)
 *   - Typically used in stages: multiple CSAs reduce many operands to two, then final adder sums them
 * 
 * Characteristics:
 *   - Area: Moderate - full adders for each bit
 *   - Delay: O(1) - constant time, no carry propagation
 *   - Power: Moderate - all bits compute simultaneously
 *   - Use case: Multi-operand addition, multiplication partial product reduction
 * 
 * Key Difference from Regular Adders:
 *   - Regular adders: cin is a single bit, carries propagate between positions
 *   - Carry-save: cin is a vector (one bit per position), no carry propagation
 *   - Output: sum and cout are both vectors (not a single carry-out)
 * 
 * Typical Usage:
 *   - Stage 1: CSA reduces 3 operands to 2
 *   - Stage 2: CSA reduces 3 operands to 2 (one from stage 1)
 *   - Continue until 2 operands remain
 *   - Final stage: Regular adder sums the final 2 operands
 * 
 * @param DATA_WIDTH Width of input operands and outputs (default: 32)
 */
module carry_save_adder #(
    parameter DATA_WIDTH = 32    // Width of the operands
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire [DATA_WIDTH-1:0] cin,   // Carry-in vector (one bit per position, NOT a single carry)
    output wire [DATA_WIDTH-1:0] sum, // Sum output vector
    output wire [DATA_WIDTH-1:0] cout  // Carry-out vector (one bit per position, NOT a single carry)
);

    // Generate full adders for each bit position
    // Each bit is independent - no carry propagation between bits
    // This is the key characteristic of carry-save adders
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : carry_save_logic
            // Carry Save Adder logic for each bit:
            // Each bit position computes independently using a full adder
            // 
            // Sum calculation: XOR of all three inputs
            // sum[i] = a[i] XOR b[i] XOR cin[i]
            // This is the same as a regular full adder
            assign sum[i] = a[i] ^ b[i] ^ cin[i];

            // Carry-out calculation: optimized form
            // cout[i] = (a[i] & b[i]) | ((a[i] | b[i]) & cin[i])
            //   - First term: carry generated when both a[i] and b[i] are 1
            //   - Second term: carry propagated when at least one of a[i] or b[i] is 1 AND cin[i] is 1
            // Note: This carry-out is SAVED (not propagated to next bit) - hence "carry-save"
            assign cout[i] = (a[i] & b[i]) | ((a[i] | b[i]) & cin[i]);
        end
    endgenerate

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_carry_select.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */

/**
 * Parameterized Carry-Select Adder (CSA)
 * 
 * This module implements a carry-select adder, which pre-computes sums for both
 * possible carry-in values (0 and 1) and then selects the correct result based
 * on the actual carry-in. This eliminates the carry propagation delay between blocks.
 * 
 * Algorithm:
 *   - First block: Standard ripple-carry adder (computes carry-out)
 *   - Subsequent blocks: Two parallel ripple-carry adders
 *     * One assumes carry-in = 0
 *     * One assumes carry-in = 1
 *   - When carry-in is known, select the appropriate pre-computed result
 *   - This allows blocks to compute in parallel while waiting for carry-in
 * 
 * Characteristics:
 *   - Area: Large - approximately 2x ripple carry (due to duplicate adders)
 *   - Delay: O(n/BLOCK_SIZE) - much faster than ripple carry
 *   - Power: High - both paths compute simultaneously
 *   - Use case: Medium-to-large adders where speed is critical and area is acceptable
 * 
 * Trade-offs:
 *   - Larger BLOCK_SIZE reduces delay but increases area (more duplicate logic)
 *   - Typical BLOCK_SIZE values: 4-8 bits (balanced), 16+ (very fast but large area)
 *   - The first block doesn't need duplication since its carry-in is known (cin)
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 64)
 * @param BLOCK_SIZE Size of each carry-select block (default: 8)
 */
module carry_select_adder #(
    parameter DATA_WIDTH = 64,        // Width of the operands - increased from 32 to 64
    parameter BLOCK_SIZE = 8          // Size of each carry-select block - increased from 4 to 8
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow
);

    // Calculate the number of blocks needed
    // Ceiling division ensures we have enough blocks even if DATA_WIDTH is not a multiple of BLOCK_SIZE
    localparam NUM_BLOCKS = (DATA_WIDTH + BLOCK_SIZE - 1) / BLOCK_SIZE;

    // Internal wires for block interconnection
    // block_carry[i] is the carry entering block i
    // In carry-select adders, combinatorial feedback is by design (carry propagates between blocks)
    wire [NUM_BLOCKS:0] block_carry;
    assign block_carry[0] = cin;      // Input carry enters the first block
    assign cout = block_carry[NUM_BLOCKS]; // Output carry exits the last block

    // Generate the adder blocks
    generate
        // First block is a regular ripple-carry adder (inline RCA logic)
        // No need for carry-select here since carry-in is known (cin)
        begin : first_block_logic
            // Calculate the actual size of the first block
            // If DATA_WIDTH < BLOCK_SIZE, only process DATA_WIDTH bits
            localparam FIRST_BLOCK_SIZE = (DATA_WIDTH < BLOCK_SIZE) ? DATA_WIDTH : BLOCK_SIZE;
            wire [FIRST_BLOCK_SIZE-1:0] first_block_sum;

            // Inline RCA logic for first block
            // Standard ripple-carry adder implementation
            wire [FIRST_BLOCK_SIZE:0] first_block_carry;
            assign first_block_carry[0] = block_carry[0];  // Carry-in from input
            assign block_carry[1] = first_block_carry[FIRST_BLOCK_SIZE];  // Carry-out to next block

            genvar k_first;
            for (k_first = 0; k_first < FIRST_BLOCK_SIZE; k_first = k_first + 1) begin : rca_bits
                // Full adder logic for each bit in the first block
                // Sum: XOR of all three inputs
                assign first_block_sum[k_first] = a[k_first] ^ b[k_first] ^ first_block_carry[k_first];

                // Carry-out: generate OR propagate
                // Standard form: (a & b) | (a & c) | (b & c)
                assign first_block_carry[k_first+1] = (a[k_first] & b[k_first]) | (a[k_first] & first_block_carry[k_first]) | (b[k_first] & first_block_carry[k_first]);
            end

            // Output sum for the first block
            assign sum[FIRST_BLOCK_SIZE-1:0] = first_block_sum;
        end

        // Remaining blocks use carry-select logic
        // These blocks pre-compute results for both carry-in possibilities
        genvar i;
        for (i = 1; i < NUM_BLOCKS; i = i + 1) begin : carry_select_blocks
            // Calculate the width of this block
            // The last block may be smaller if DATA_WIDTH is not a multiple of BLOCK_SIZE
            localparam CURRENT_BLOCK_SIZE = ((i+1)*BLOCK_SIZE <= DATA_WIDTH) ? 
                                             BLOCK_SIZE : 
                                             DATA_WIDTH - (i*BLOCK_SIZE);

            // Calculate start and end indices for this block
            // Used to extract the relevant bit range from the full-width operands
            localparam START_IDX = i * BLOCK_SIZE;
            localparam END_IDX = START_IDX + CURRENT_BLOCK_SIZE - 1;

            // Block inputs: extract the relevant bits for this block
            wire [CURRENT_BLOCK_SIZE-1:0] block_a = a[END_IDX:START_IDX];
            wire [CURRENT_BLOCK_SIZE-1:0] block_b = b[END_IDX:START_IDX];

            // Two possible results for carry-in 0 and 1
            // Both are computed in parallel, then one is selected based on actual carry-in
            wire [CURRENT_BLOCK_SIZE-1:0] sum_cin_0, sum_cin_1;  // Sums for carry-in = 0 and 1
            wire cout_cin_0, cout_cin_1;                          // Carry-outs for carry-in = 0 and 1

            // Inline RCA logic for carry-in = 0
            // Pre-compute what the result would be if carry-in to this block is 0
            wire [CURRENT_BLOCK_SIZE:0] carry_cin_0;
            assign carry_cin_0[0] = 1'b0;  // Assume carry-in = 0
            assign cout_cin_0 = carry_cin_0[CURRENT_BLOCK_SIZE];  // Carry-out from this assumption

            genvar k;
            for (k = 0; k < CURRENT_BLOCK_SIZE; k = k + 1) begin : rca_cin_0
                // Full adder logic assuming carry-in = 0
                assign sum_cin_0[k] = block_a[k] ^ block_b[k] ^ carry_cin_0[k];
                assign carry_cin_0[k+1] = (block_a[k] & block_b[k]) | (block_a[k] & carry_cin_0[k]) | (block_b[k] & carry_cin_0[k]);
            end

            // Inline RCA logic for carry-in = 1
            // Pre-compute what the result would be if carry-in to this block is 1
            wire [CURRENT_BLOCK_SIZE:0] carry_cin_1;
            assign carry_cin_1[0] = 1'b1;  // Assume carry-in = 1
            assign cout_cin_1 = carry_cin_1[CURRENT_BLOCK_SIZE];  // Carry-out from this assumption

            for (k = 0; k < CURRENT_BLOCK_SIZE; k = k + 1) begin : rca_cin_1
                // Full adder logic assuming carry-in = 1
                assign sum_cin_1[k] = block_a[k] ^ block_b[k] ^ carry_cin_1[k];
                assign carry_cin_1[k+1] = (block_a[k] & block_b[k]) | (block_a[k] & carry_cin_1[k]) | (block_b[k] & carry_cin_1[k]);
            end

            // Select the correct output based on carry-in from previous block
            // This selection happens after both paths have computed, eliminating carry propagation delay
            wire select = block_carry[i];  // Carry-in to this block (from previous block)

            // Multiplex the sum: select sum_cin_1 if carry-in is 1, else sum_cin_0
            assign sum[END_IDX:START_IDX] = select ? sum_cin_1 : sum_cin_0;

            // Multiplex the carry-out: select cout_cin_1 if carry-in is 1, else cout_cin_0
            assign block_carry[i+1] = select ? cout_cin_1 : cout_cin_0;
        end
    endgenerate

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */

db_carry_skip.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */

/**
 * Parameterized Carry-Skip Adder
 * 
 * This module implements a carry-skip adder (also known as carry-bypass adder),
 * which is identical to the carry-bypass adder. The name "skip" emphasizes that
 * the carry can skip over blocks when all bits in the block propagate.
 * 
 * Algorithm:
 *   - Operands divided into blocks of BLOCK_SIZE bits
 *   - Each block uses a ripple-carry adder
 *   - If all bits in block propagate (P[i] = 1 for all i), carry skips the block
 *   - Otherwise, carry propagates normally through the block
 * 
 * Characteristics:
 *   - Area: Moderate - slightly more than ripple carry (skip logic)
 *   - Delay: O(n/BLOCK_SIZE) - faster than ripple when skips occur
 *   - Power: Moderate - skip reduces switching when active
 *   - Use case: Medium-width adders where some patterns benefit from skipping
 * 
 * Skip Condition:
 *   - If all bits propagate (P[i] = 1 for all i in block):
 *     * Carry skips: block_carry[i+1] = block_carry[i]
 *   - Otherwise:
 *     * Carry propagates normally: block_carry[i+1] = block_c[CURRENT_BLOCK_SIZE]
 * 
 * Note: This is functionally identical to carry-bypass adder, just different naming.
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 * @param BLOCK_SIZE Size of each block (default: 4)
 */
module carry_skip_adder #(
    parameter DATA_WIDTH = 32,    // Width of the operands
    parameter BLOCK_SIZE = 4      // Size of each block
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow
);

    // Calculate the number of blocks needed
    // Ceiling division ensures we have enough blocks even if DATA_WIDTH is not a multiple of BLOCK_SIZE
    localparam NUM_BLOCKS = (DATA_WIDTH + BLOCK_SIZE - 1) / BLOCK_SIZE;

    // Propagate signals for each bit
    // P[i] = 1 means carry propagates through bit i (a[i] XOR b[i] = 1)
    wire [DATA_WIDTH-1:0] p;

    // Generate propagate signals for each bit position
    // These are computed independently and in parallel
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : gen_propagate
            // Propagate: when a and b are different (XOR = 1)
            // P[i] = 1 means: if carry-in is 1, carry-out will be 1; if carry-in is 0, carry-out will be 0
            assign p[i] = a[i] ^ b[i];
        end
    endgenerate

    // Internal carries between blocks
    // block_carry[i] is the carry entering block i
    wire [NUM_BLOCKS:0] block_carry;
    assign block_carry[0] = cin;      // Input carry enters the first block
    assign cout = block_carry[NUM_BLOCKS]; // Output carry exits the last block

    // Generate the carry-skip blocks
    // Each block can skip carry propagation if all bits propagate
    genvar j;
    generate
        for (i = 0; i < NUM_BLOCKS; i = i + 1) begin : blocks
            // Calculate the width of this block
            // The last block may be smaller if DATA_WIDTH is not a multiple of BLOCK_SIZE
            localparam CURRENT_BLOCK_SIZE = ((i+1)*BLOCK_SIZE <= DATA_WIDTH) ? 
                                            BLOCK_SIZE : 
                                            DATA_WIDTH - (i*BLOCK_SIZE);

            // Calculate start and end indices for this block
            // Used to extract the relevant bit range from the full-width operands
            localparam START_IDX = i * BLOCK_SIZE;
            localparam END_IDX = START_IDX + CURRENT_BLOCK_SIZE - 1;

            // Block inputs: extract the relevant bits for this block
            wire [CURRENT_BLOCK_SIZE-1:0] block_a = a[END_IDX:START_IDX];
            wire [CURRENT_BLOCK_SIZE-1:0] block_b = b[END_IDX:START_IDX];
            wire [CURRENT_BLOCK_SIZE-1:0] block_p = p[END_IDX:START_IDX];  // Propagate signals for this block

            // Block sum and carry signals
            wire [CURRENT_BLOCK_SIZE-1:0] block_sum;
            wire [CURRENT_BLOCK_SIZE:0] block_c;  // Carries within this block
            assign block_c[0] = block_carry[i];  // Carry entering this block

            // Ripple Carry Adder for this block
            // Computes sum and carry-out assuming normal propagation
            for (j = 0; j < CURRENT_BLOCK_SIZE; j = j + 1) begin : rca
                // Sum: XOR propagate with carry-in
                // Since P = a XOR b, sum = P XOR carry_in = a XOR b XOR carry_in
                assign block_sum[j] = block_p[j] ^ block_c[j];

                // Carry-out: generate OR propagate
                // Standard full adder carry formula
                assign block_c[j+1] = (block_a[j] & block_b[j]) | 
                                     ((block_a[j] | block_b[j]) & block_c[j]);
            end

            // Connect block sum to the main sum output
            assign sum[END_IDX:START_IDX] = block_sum;

            // Calculate if all bits in this block propagate
            // If all P[i] = 1, then the entire block propagates carry
            // This is computed as the AND of all propagate signals in the block
            wire block_propagate = &block_p;

            // Skip logic: If all bits propagate, we can skip and just forward the carry
            // This is the key optimization: when all bits propagate, carry skips the block
            // 
            // If block_propagate = 1: Carry skips the block (no delay through block)
            //   block_carry[i+1] = block_carry[i]
            // If block_propagate = 0: Carry propagates normally through the block
            //   block_carry[i+1] = block_c[CURRENT_BLOCK_SIZE]
            assign block_carry[i+1] = block_propagate ? block_carry[i] : block_c[CURRENT_BLOCK_SIZE];
        end
    endgenerate

endmodule

