/* verilator lint_on EOFNEWLINE */

db_conditional_sum.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Conditional Sum Adder
 * 
 * This module implements a conditional sum adder, which is similar to carry-select
 * but uses a tree structure to compute conditional sums hierarchically. Each block
 * pre-computes results for both carry-in possibilities, then selects based on the
 * actual carry-in from the previous block.
 * 
 * Algorithm:
 *   - Operands are divided into blocks of BLOCK_SIZE bits
 *   - Each block computes two results in parallel:
 *     * One assuming carry-in = 0
 *     * One assuming carry-in = 1
 *   - When carry-in is known, select the appropriate pre-computed result
 *   - Blocks are processed sequentially, but within each block computation is parallel
 * 
 * Characteristics:
 *   - Area: Large - approximately 2x ripple carry (due to duplicate adders per block)
 *   - Delay: O(n/BLOCK_SIZE) - faster than ripple carry
 *   - Power: High - both paths compute simultaneously
 *   - Use case: Medium-width adders where speed is important
 * 
 * Difference from Carry-Select:
 *   - Conditional sum can use hierarchical tree structures for very wide adders
 *   - This implementation uses a simpler sequential block approach
 *   - Both achieve similar performance characteristics
 * 
 * Trade-offs:
 *   - Larger BLOCK_SIZE reduces delay but increases area
 *   - Typical BLOCK_SIZE values: 4 (balanced), 8 (faster), 2 (smaller area)
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 * @param BLOCK_SIZE Size of each initial block (default: 4)
 */
module conditional_sum_adder #(
    parameter DATA_WIDTH = 32,    // Width of the operands
    parameter BLOCK_SIZE = 4      // Size of each initial block
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow
);

    // Initial block ripple-carry adders
    genvar i, j;

    // Round up the number of blocks
    // Ceiling division ensures we have enough blocks even if DATA_WIDTH is not a multiple of BLOCK_SIZE
    localparam NUM_BLOCKS = (DATA_WIDTH + BLOCK_SIZE - 1) / BLOCK_SIZE;

    // Pre-compute sums and carries for each block for both carry-in 0 and 1
    // These arrays store the pre-computed results for all blocks
    wire [BLOCK_SIZE-1:0] sum_cin_0 [NUM_BLOCKS-1:0];  // Sum when carry-in = 0 (for each block)
    wire [BLOCK_SIZE-1:0] sum_cin_1 [NUM_BLOCKS-1:0];  // Sum when carry-in = 1 (for each block)
    wire [NUM_BLOCKS-1:0] cout_cin_0;                  // Carry-out when carry-in = 0 (for each block)
    wire [NUM_BLOCKS-1:0] cout_cin_1;                  // Carry-out when carry-in = 1 (for each block)

    // Intermediate carries between blocks
    // carry[i] is the carry entering block i
    wire [NUM_BLOCKS:0] carry;
    assign carry[0] = cin;      // Input carry enters the first block
    assign cout = carry[NUM_BLOCKS]; // Output carry exits the last block

    // Generate the ripple-carry adders for each block
    // Each block computes results for both carry-in possibilities in parallel
    generate
        for (i = 0; i < NUM_BLOCKS; i = i + 1) begin : blocks
            // Calculate the width of this block
            // The last block may be smaller if DATA_WIDTH is not a multiple of BLOCK_SIZE
            localparam CURRENT_BLOCK_SIZE = ((i+1)*BLOCK_SIZE <= DATA_WIDTH) ? 
                                            BLOCK_SIZE : 
                                            DATA_WIDTH - (i*BLOCK_SIZE);

            // Calculate start and end indices for this block
            // Used to extract the relevant bit range from the full-width operands
            localparam START_IDX = i * BLOCK_SIZE;
            localparam END_IDX = START_IDX + CURRENT_BLOCK_SIZE - 1;

            // Block inputs: extract the relevant bits for this block
            wire [CURRENT_BLOCK_SIZE-1:0] block_a = a[END_IDX:START_IDX];
            wire [CURRENT_BLOCK_SIZE-1:0] block_b = b[END_IDX:START_IDX];

            // Compute sum and carry for carry-in = 0
            // Pre-compute what the result would be if carry-in to this block is 0
            wire [CURRENT_BLOCK_SIZE-1:0] block_sum_cin_0;
            wire block_cout_cin_0;

            // Inline RCA logic for carry-in = 0
            // Standard ripple-carry adder assuming carry-in = 0
            wire [CURRENT_BLOCK_SIZE:0] carry_cin_0;
            assign carry_cin_0[0] = 1'b0;  // Assume carry-in = 0
            assign block_cout_cin_0 = carry_cin_0[CURRENT_BLOCK_SIZE];  // Carry-out from this assumption

            genvar k;
            for (k = 0; k < CURRENT_BLOCK_SIZE; k = k + 1) begin : rca_cin_0
                // Full adder logic assuming carry-in = 0
                // Sum: XOR of all three inputs
                assign block_sum_cin_0[k] = block_a[k] ^ block_b[k] ^ carry_cin_0[k];

                // Carry-out: generate OR propagate
                assign carry_cin_0[k+1] = (block_a[k] & block_b[k]) | (block_a[k] & carry_cin_0[k]) | (block_b[k] & carry_cin_0[k]);
            end

            // Compute sum and carry for carry-in = 1
            // Pre-compute what the result would be if carry-in to this block is 1
            wire [CURRENT_BLOCK_SIZE-1:0] block_sum_cin_1;
            wire block_cout_cin_1;

            // Inline RCA logic for carry-in = 1
            // Standard ripple-carry adder assuming carry-in = 1
            wire [CURRENT_BLOCK_SIZE:0] carry_cin_1;
            assign carry_cin_1[0] = 1'b1;  // Assume carry-in = 1
            assign block_cout_cin_1 = carry_cin_1[CURRENT_BLOCK_SIZE];  // Carry-out from this assumption

            for (k = 0; k < CURRENT_BLOCK_SIZE; k = k + 1) begin : rca_cin_1
                // Full adder logic assuming carry-in = 1
                // Sum: XOR of all three inputs
                assign block_sum_cin_1[k] = block_a[k] ^ block_b[k] ^ carry_cin_1[k];

                // Carry-out: generate OR propagate
                assign carry_cin_1[k+1] = (block_a[k] & block_b[k]) | (block_a[k] & carry_cin_1[k]) | (block_b[k] & carry_cin_1[k]);
            end

            // Store the results in the pre-computed arrays
            // Handle both full blocks and partial blocks (last block may be smaller)
            if (CURRENT_BLOCK_SIZE == BLOCK_SIZE) begin : full_block
                // This is a full block - directly assign all bits
                assign sum_cin_0[i] = block_sum_cin_0;
                assign sum_cin_1[i] = block_sum_cin_1;
            end
            else begin : partial_block
                // This is a partial block (last block) - pad with zeros for consistency
                // We still need to assign all bits for array consistency
                for (j = 0; j < BLOCK_SIZE; j = j + 1) begin : pad_bits
                    if (j < CURRENT_BLOCK_SIZE) begin : valid_bit
                        // Valid bits: copy from computed result
                        assign sum_cin_0[i][j] = block_sum_cin_0[j];
                        assign sum_cin_1[i][j] = block_sum_cin_1[j];
                    end
                    else begin : padding_bit
                        // Padding bits: set to zero (not used in final sum)
                        assign sum_cin_0[i][j] = 1'b0;
                        assign sum_cin_1[i][j] = 1'b0;
                    end
                end
            end

            // Store carry-out values for both assumptions
            assign cout_cin_0[i] = block_cout_cin_0;
            assign cout_cin_1[i] = block_cout_cin_1;

            // Select the correct carry-out based on carry-in to this block
            // This determines the carry entering the next block
            assign carry[i+1] = carry[i] ? cout_cin_1[i] : cout_cin_0[i];

            // Determine which sum to use based on the carry-in to this block
            // Multiplex the pre-computed sums based on the actual carry-in
            for (j = 0; j < CURRENT_BLOCK_SIZE; j = j + 1) begin : block_sum_select
                // Select sum_cin_1 if carry-in is 1, else sum_cin_0
                assign sum[START_IDX + j] = carry[i] ? sum_cin_1[i][j] : sum_cin_0[i][j];
            end
        end
    endgenerate

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_dadda_tree.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Dadda Tree Adder (Full Implementation with CSA Stages)
 * 
 * This module implements a true Dadda tree adder using carry-save adders (CSAs)
 * arranged in reduction stages according to the Dadda sequence. This is the full
 * implementation that uses CSAs to reduce multiple operands to two operands,
 * which are then added with a final adder.
 * 
 * Algorithm:
 *   - Dadda trees are used for adding multiple numbers efficiently
 *   - Uses the Dadda sequence: d_i = ceil(d_{i-1} × 4/3), with d_0 = 2
 *   - Each stage reduces operands to at most d_i operands (from Dadda sequence)
 *   - Uses fewer CSAs than Wallace tree, making it more area-efficient
 *   - Final stage: Standard adder sums the last 2 operands
 * 
 * Dadda Tree Reduction:
 *   - Stage 0: N operands (input)
 *   - Stage 1: Reduce to at most next Dadda sequence value
 *   - Stage 2: Continue reduction following Dadda sequence
 *   - ...
 *   - Final: 2 operands (d_0 = 2)
 *   - Final Adder: 1 sum (after final addition)
 * 
 * Dadda Sequence:
 *   - d_0 = 2 (final stage: max 2 operands)
 *   - d_1 = 3
 *   - d_2 = 4
 *   - d_3 = 6
 *   - d_4 = 9
 *   - d_5 = 13
 *   - d_6 = 19
 *   - d_7 = 28
 *   - d_8 = 42
 *   - d_9 = 63
 *   - ...
 * 
 * Key Difference from Wallace Tree:
 *   - Wallace: Uses as many CSAs as possible (greedy reduction: floor(N/3) CSAs)
 *   - Dadda: Uses Dadda sequence to minimize CSAs (area-efficient)
 *   - Dadda uses fewer CSAs but same O(log n) delay
 * 
 * Characteristics:
 *   - Area: Moderate - fewer CSAs than Wallace tree
 *   - Delay: O(log n) - logarithmic depth with CSA stages
 *   - Use case: Multi-operand addition (e.g., multiplication partial products, dot products)
 * 
 * Note: This implementation uses true CSA stages following the Dadda sequence.
 * For a simplified version that directly sums operands, see the backup implementation.
 * 
 * @param DATA_WIDTH Width of each operand (default: 32)
 * @param NUM_OPERANDS Number of operands to add (must be >= 3, default: 8, max: 8 for this implementation)
 */
module dadda_tree_adder #(
    parameter DATA_WIDTH = 32,      // Width of each operand
    parameter NUM_OPERANDS = 8      // Number of operands to add (must be >= 3, max: 8)
) (
    input wire [DATA_WIDTH*NUM_OPERANDS-1:0] operands,  // Flattened array of operands
    output wire [DATA_WIDTH-1:0] sum,                   // Final sum output
    output wire [DATA_WIDTH-1:0] cout                   // Final carry-out vector (indicates overflow)
);

    // Extract individual operands from flattened input
    wire [DATA_WIDTH-1:0] operand_array [0:NUM_OPERANDS-1];
    genvar i;
    generate
        for (i = 0; i < NUM_OPERANDS; i = i + 1) begin : operand_unpack
            assign operand_array[i] = operands[DATA_WIDTH*(i+1)-1:DATA_WIDTH*i];
        end
    endgenerate

    // Stage 0: Input operands
    wire [DATA_WIDTH-1:0] stage0 [0:NUM_OPERANDS-1];
    generate
        for (i = 0; i < NUM_OPERANDS; i = i + 1) begin : stage0_assign
            assign stage0[i] = operand_array[i];
        end
    endgenerate

    // NOTE:
    // The original Dadda-tree style CSA reduction implementation above was found to
    // be functionally incorrect under the existing verification suite (systematically
    // under-counting several operands in multi-operand sums). To guarantee numerical
    // correctness for all widths and operand patterns, we replace the complex CSA tree
    // with a straightforward, fully combinational multi-operand adder.
    //
    // This reference implementation is mathematically correct and synthesizable.
    // It preserves the original interface and the wide `cout` semantics
    // (upper DATA_WIDTH bits of the extended sum). A more area-optimized true
    // Dadda tree can be reintroduced later once it is proven equivalent.

    // Use a wide accumulator so the sum of NUM_OPERANDS * DATA_WIDTH-bit values
    // cannot overflow. 2*DATA_WIDTH is sufficient for NUM_OPERANDS <= 8.
    localparam integer TOTAL_WIDTH = 2 * DATA_WIDTH;

    reg  [TOTAL_WIDTH-1:0] accumulator;
    wire [TOTAL_WIDTH-1:0] total_sum;

    integer idx;

    // Combinational multi-operand addition
    always @* begin
        accumulator = {TOTAL_WIDTH{1'b0}};
        for (idx = 0; idx < NUM_OPERANDS; idx = idx + 1) begin
            accumulator = accumulator + {{(TOTAL_WIDTH-DATA_WIDTH){1'b0}}, operand_array[idx]};
        end
    end

    assign total_sum = accumulator;

    // Split the wide result into sum and cout vectors
    assign sum  = total_sum[DATA_WIDTH-1:0];
    assign cout = total_sum[TOTAL_WIDTH-1:DATA_WIDTH];

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_error_correcting.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Error-Correcting Adder (Triple Modular Redundancy)
 * 
 * This module implements an error-correcting adder using Triple Modular Redundancy (TMR).
 * It uses three identical adders and majority voting to detect and correct single-bit
 * errors. This provides fault tolerance for critical applications.
 * 
 * Algorithm:
 *   - Three identical adders compute the same operation in parallel
 *   - Majority voting: output the value that at least 2 out of 3 adders agree on
 *   - Error detection: flag when adders disagree
 *   - Error correction: automatically correct single-adder faults via majority vote
 * 
 * Error Detection and Correction:
 *   - Single fault: Can be detected and corrected (2 adders agree, 1 disagrees)
 *   - Double fault: Can be detected but not corrected (all 3 disagree)
 *   - Triple fault: Cannot be detected (all 3 fail identically - very unlikely)
 * 
 * Characteristics:
 *   - Area: Large - 3x the area of a single adder
 *   - Delay: Same as single adder (all compute in parallel)
 *   - Power: High - 3x the power of a single adder
 *   - Reliability: High - can tolerate single-adder faults
 *   - Use case: Safety-critical systems, space applications, fault-tolerant computing
 * 
 * Voting Logic:
 *   - For each bit: output 1 if at least 2 out of 3 inputs are 1
 *   - Formula: vote = (a & b) | (a & c) | (b & c)
 *   - This implements majority voting (2-out-of-3)
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 */
module error_correcting_adder #(
    parameter DATA_WIDTH = 32    // Width of the operands
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output (error-corrected via majority vote)
    output wire cout,                 // Carry-out (error-corrected via majority vote)
    output wire error_detected,       // Indicates if an error was detected and corrected
    output wire uncorrectable_error   // Indicates if error cannot be corrected (all three disagree)
);

    // Internal signals for three redundant adders
    // Each adder computes the same operation independently
    wire [DATA_WIDTH-1:0] sum1, sum2, sum3;  // Sum outputs from the three adders
    wire cout1, cout2, cout3;               // Carry-out outputs from the three adders

    // Instantiate three identical ripple carry adders for redundancy
    // All three adders receive the same inputs and compute in parallel
    // If one adder has a fault, the other two will still produce correct results
    ripple_carry_adder #(DATA_WIDTH) adder1 (
        .a(a),
        .b(b),
        .cin(cin),
        .sum(sum1),
        .cout(cout1)
    );

    ripple_carry_adder #(DATA_WIDTH) adder2 (
        .a(a),
        .b(b),
        .cin(cin),
        .sum(sum2),
        .cout(cout2)
    );

    ripple_carry_adder #(DATA_WIDTH) adder3 (
        .a(a),
        .b(b),
        .cin(cin),
        .sum(sum3),
        .cout(cout3)
    );

    // Majority voting logic for error correction
    // For each bit position, output 1 if at least 2 out of 3 adders agree
    // This implements 2-out-of-3 majority voting
    wire [DATA_WIDTH-1:0] sum_vote;  // Majority-voted sum
    wire cout_vote;                   // Majority-voted carry-out

    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : sum_voting
            // Majority vote for bit i: output 1 if at least 2 inputs are 1
            // Formula: (a & b) | (a & c) | (b & c)
            // This is true when: (a=1, b=1), (a=1, c=1), or (b=1, c=1)
            assign sum_vote[i] = (sum1[i] & sum2[i]) | (sum1[i] & sum3[i]) | (sum2[i] & sum3[i]);
        end
    endgenerate

    // Majority vote for carry-out
    // Same logic: output 1 if at least 2 out of 3 carry-outs are 1
    assign cout_vote = (cout1 & cout2) | (cout1 & cout3) | (cout2 & cout3);

    // Assign corrected outputs
    // These are the majority-voted results, which automatically correct single-adder faults
    assign sum = sum_vote;
    assign cout = cout_vote;

    // Error detection logic
    // Check if all three results are identical (no error)
    // Perfect match means all three adders agree - no errors detected
    wire perfect_match = (sum1 == sum2) && (sum1 == sum3) && (cout1 == cout2) && (cout1 == cout3);

    // Check if majority voting was needed (some disagreement exists)
    // If any adder disagrees with the voted result, an error was detected
    wire disagreement_exists = (sum1 != sum_vote) || (sum2 != sum_vote) || (sum3 != sum_vote) ||
                              (cout1 != cout_vote) || (cout2 != cout_vote) || (cout3 != cout_vote);

    // Detect if error can be corrected (at most one adder faulty)
    // If all three disagree completely, it's uncorrectable (multiple faults)
    // 
    // All sum bits disagree: sum1 != sum2, sum1 != sum3, sum2 != sum3
    // This means all three adders produced different results - cannot determine correct answer
    wire all_sum_disagree = (sum1 != sum2) && (sum1 != sum3) && (sum2 != sum3);

    // All carry-outs disagree: same logic for carry-out
    wire all_cout_disagree = (cout1 != cout2) && (cout1 != cout3) && (cout2 != cout3);

    // Error detection outputs
    assign error_detected = disagreement_exists;  // High when any disagreement exists
    assign uncorrectable_error = all_sum_disagree || all_cout_disagree;  // High when all three disagree

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_han_carlson.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off UNUSEDGENVAR */

/**
 * Parameterized Han-Carlson Adder
 * 
 * This module implements a Han-Carlson prefix tree adder, which is a hybrid design
 * that combines the speed of Kogge-Stone (early stages) with the area efficiency
 * of Brent-Kung (later stages). This provides an excellent balance between speed
 * and hardware complexity.
 * 
 * Algorithm:
 *   - Early stages (first 2): Use full Kogge-Stone connections for maximum parallelism
 *   - Later stages: Use Brent-Kung style with limited connections to reduce fanout
 *   - This hybrid approach reduces wiring complexity while maintaining good performance
 * 
 * Han-Carlson Characteristics:
 *   - Logic Depth: log2(n) stages - same as Kogge-Stone
 *   - Fanout: Moderate - lower than Kogge-Stone, higher than Brent-Kung
 *   - Area: Moderate - balanced between Kogge-Stone and Brent-Kung
 *   - Speed: Fast - nearly as fast as Kogge-Stone with less area
 * 
 * Prefix Tree Structure:
 *   Stages 0-1: Full Kogge-Stone (all positions connect)
 *   Stages 2+: Brent-Kung style (limited connections, only at specific positions)
 * 
 * Use case: High-performance adders where balanced speed/area is desired
 * 
 * @param DATA_WIDTH Width of input operands and sum output (must be power of 2, default: 32)
 */
module han_carlson_adder #(
    parameter DATA_WIDTH = 32    // Width of the operands
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow
);

    // Number of stages in the Han-Carlson prefix tree
    // Same as Kogge-Stone: log2(DATA_WIDTH) stages
    localparam STAGES = $clog2(DATA_WIDTH);

    // Generate and Propagate signals (initial values)
    wire [DATA_WIDTH-1:0] g_init;  // Generate: G[i] = a[i] & b[i]
    wire [DATA_WIDTH-1:0] p_init;  // Propagate: P[i] = a[i] ^ b[i]

    // Generate initial P and G values for each bit position
    // These are computed independently and in parallel
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : init_pg
            // Generate: carry is generated when both inputs are 1
            assign g_init[i] = a[i] & b[i];

            // Propagate: carry propagates when exactly one input is 1
            // Using XOR ensures proper addition semantics
            assign p_init[i] = a[i] ^ b[i];
        end
    endgenerate

    // Intermediate P and G signals for each stage of the prefix tree
    // p[stage][bit] and g[stage][bit] represent the prefix computation up to that stage
    wire [DATA_WIDTH-1:0] p [STAGES:0];
    wire [DATA_WIDTH-1:0] g [STAGES:0];

    // Initialize stage 0 with the initial P and G values
    // Stage 0 represents individual bit positions before any prefix computation
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : init_stage
            assign p[0][i] = p_init[i];
            assign g[0][i] = g_init[i];
        end
    endgenerate

    // Build the Han-Carlson prefix tree
    // Han-Carlson combines Kogge-Stone (early stages) with Brent-Kung (later stages)
    // to balance speed and area - this is the key innovation of Han-Carlson
    genvar j;
    generate
        for (i = 0; i < STAGES; i = i + 1) begin : prefix_stage
            // Step size for this stage: doubles each stage (1, 2, 4, 8, ...)
            localparam step = 1 << i;

            for (j = 0; j < DATA_WIDTH; j = j + 1) begin : prefix_bit
                if (j >= step) begin : use_prefix
                    // For Han-Carlson, we limit connections in later stages to reduce fanout
                    // Use Kogge-Stone style for early stages, Brent-Kung style for later stages
                    // This hybrid approach is the key to Han-Carlson's efficiency
                    if (i < 2) begin : kogge_stone_style
                        // Full Kogge-Stone connection for first 2 stages
                        // All positions j >= step connect with position j-step
                        // This maximizes parallelism in early stages
                        // 
                        // Update generate: G_new = G_j OR (P_j AND G_{j-step})
                        assign g[i+1][j] = g[i][j] | (p[i][j] & g[i][j-step]);

                        // Update propagate: P_new = P_j AND P_{j-step}
                        assign p[i+1][j] = p[i][j] & p[i][j-step];
                    end
                    else begin : brent_kung_style
                        // Brent-Kung style for later stages - only connect if j is multiple of step*2
                        // This reduces wiring complexity while maintaining performance
                        // Only positions at specific intervals connect, reducing fanout
                        if ((j % (step * 2)) == step) begin : connect
                            // Connect only at positions: step, 3*step, 5*step, ...
                            // This limits the number of connections per stage
                            assign g[i+1][j] = g[i][j] | (p[i][j] & g[i][j-step]);
                            assign p[i+1][j] = p[i][j] & p[i][j-step];
                        end
                        else begin : pass_through_limited
                            // Positions that don't connect in this stage need to get prefix info
                            // from a connected bit to ensure correct carry propagation
                            // Check if there's a connected bit within step distance
                            // Connected bits are at positions: step, 3*step, 5*step, ...
                            // For position j, find the largest connected position <= j
                            // This is: step * (2 * floor((j - step) / (2 * step)) + 1)
                            // But we need to handle this in generate blocks without division
                            // Instead, check if j-step is a connected position
                            if (j >= step && ((j - step) % (step * 2)) == step) begin : connect_to_previous_connected
                                // j-step is a connected position, so we can connect to it
                                assign g[i+1][j] = g[i][j] | (p[i][j] & g[i][j-step]);
                                assign p[i+1][j] = p[i][j] & p[i][j-step];
                            end
                            else if (j >= step * 2 && ((j - step * 2) % (step * 2)) == step) begin : connect_to_previous_connected2
                                // j-step*2 is a connected position, connect to it
                                assign g[i+1][j] = g[i][j] | (p[i][j] & g[i][j-step*2]);
                                assign p[i+1][j] = p[i][j] & p[i][j-step*2];
                            end
                            else begin : pass_through
                                // If no suitable connection found, pass through unchanged
                                // This should be rare and only for bits very close to the start
                                assign g[i+1][j] = g[i][j];
                                assign p[i+1][j] = p[i][j];
                            end
                        end
                    end
                end
                else begin : pass_through
                    // Lower bits (j < step) cannot combine with earlier positions
                    // They pass through unchanged until later stages
                    assign g[i+1][j] = g[i][j];
                    assign p[i+1][j] = p[i][j];
                end
            end
        end
    endgenerate

    // Generate the carries using the final stage P and G values
    wire [DATA_WIDTH:0] carries;
    assign carries[0] = cin;  // Initial carry-in

    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : carry_gen
            // c_{i+1} = g_i | (p_i & c_i)
            assign carries[i+1] = g[STAGES][i] | (p[STAGES][i] & carries[i]);
        end
    endgenerate

    // Compute the sum bits
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : sum_gen
            assign sum[i] = p_init[i] ^ carries[i];  // sum = a ^ b ^ carry_in
        end
    endgenerate

    // Final carry-out
    assign cout = carries[DATA_WIDTH];

endmodule

