/**
 * Parameterized Manchester Adder
 * 
 * This module implements a Manchester carry chain adder, which pre-computes results
 * for both possible carry-in values (0 and 1) within each group, then selects the
 * correct result based on the actual carry-in. This is similar to carry-select but
 * uses generate/propagate signals for more efficient computation.
 * 
 * Algorithm:
 *   - Operands divided into groups of GROUP_SIZE bits
 *   - For each group, compute two carry chains in parallel:
 *     * One assuming carry-in = 0
 *     * One assuming carry-in = 1
 *   - When actual carry-in is known, select the appropriate pre-computed result
 *   - This eliminates carry propagation delay within groups
 * 
 * Manchester Characteristics:
 *   - Area: Large - approximately 2x ripple carry (due to duplicate carry chains)
 *   - Delay: O(n/GROUP_SIZE) - faster than ripple carry
 *   - Power: High - both paths compute simultaneously
 *   - Use case: Medium-width adders where speed is important
 * 
 * Difference from Carry-Select:
 *   - Manchester: Uses G/P signals and carry chains
 *   - Carry-Select: Uses full ripple-carry adders
 *   - Manchester can be more efficient in some implementations
 * 
 * Trade-offs:
 *   - Larger GROUP_SIZE reduces delay but increases area
 *   - Typical GROUP_SIZE values: 4-8 bits
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 * @param GROUP_SIZE Size of each Manchester group (default: 4)
 */
module manchester_adder #(
    parameter DATA_WIDTH = 32,    // Width of the operands
    parameter GROUP_SIZE = 4      // Size of each Manchester group
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow
);

    // Calculate the number of groups needed
    // Ceiling division ensures we have enough groups even if DATA_WIDTH is not a multiple of GROUP_SIZE
    localparam NUM_GROUPS = (DATA_WIDTH + GROUP_SIZE - 1) / GROUP_SIZE;

    // Carry signals between groups
    // group_carry[i] is the carry entering group i
    wire [NUM_GROUPS:0] group_carry;
    assign group_carry[0] = cin;      // Input carry enters the first group
    assign cout = group_carry[NUM_GROUPS]; // Output carry exits the last group

    // Generate and Propagate signals for each bit
    // These are computed independently and in parallel
    wire [DATA_WIDTH-1:0] g;          // Generate: G[i] = a[i] & b[i]
    wire [DATA_WIDTH-1:0] p;          // Propagate: P[i] = a[i] ^ b[i]

    // Generate P and G signals for each bit position
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : pg_bit_logic
            // Generate: carry is generated when both inputs are 1
            assign g[i] = a[i] & b[i];

            // Propagate: carry propagates when exactly one input is 1
            // Using XOR ensures proper addition semantics
            assign p[i] = a[i] ^ b[i];
        end
    endgenerate

    // For each group, implement Manchester carry chain logic
    // Manchester logic pre-computes results for both carry-in possibilities
    generate
        for (i = 0; i < NUM_GROUPS; i = i + 1) begin : manchester_groups
            // Calculate the width of this group
            // The last group may be smaller if DATA_WIDTH is not a multiple of GROUP_SIZE
            localparam CURRENT_GROUP_SIZE = ((i+1)*GROUP_SIZE <= DATA_WIDTH) ?
                                            GROUP_SIZE :
                                            DATA_WIDTH - (i*GROUP_SIZE);

            // Calculate start and end indices for this group
            // Used to extract the relevant bit range from the full-width operands
            localparam START_IDX = i * GROUP_SIZE;
            localparam END_IDX = START_IDX + CURRENT_GROUP_SIZE - 1;

            // Extract group signals
            // These are the G and P values for the bits in this group
            wire [CURRENT_GROUP_SIZE-1:0] group_p = p[END_IDX:START_IDX];
            wire [CURRENT_GROUP_SIZE-1:0] group_g = g[END_IDX:START_IDX];

            // Manchester logic: compute sum and carry for both possible carry-in values (0 and 1)
            // This allows the carry to "skip" through the group when possible
            // Both paths compute in parallel, then one is selected based on actual carry-in

            // Carry chain for carry_in = 0
            // Pre-compute what the carry chain would be if carry-in to this group is 0
            wire [CURRENT_GROUP_SIZE:0] carry_chain_0;
            assign carry_chain_0[0] = 1'b0;  // Assume carry-in = 0

            // Carry chain for carry_in = 1
            // Pre-compute what the carry chain would be if carry-in to this group is 1
            wire [CURRENT_GROUP_SIZE:0] carry_chain_1;
            assign carry_chain_1[0] = 1'b1;  // Assume carry-in = 1

            // Sum bits for both cases
            // Pre-compute sums for both carry-in assumptions
            wire [CURRENT_GROUP_SIZE-1:0] sum_0, sum_1;

            genvar j;
            for (j = 0; j < CURRENT_GROUP_SIZE; j = j + 1) begin : carry_propagation
                // Carry propagation for both chains
                // Standard CLA formula: c[j+1] = G[j] OR (P[j] AND c[j])
                // Compute for both carry-in assumptions
                assign carry_chain_0[j+1] = group_g[j] | (group_p[j] & carry_chain_0[j]);
                assign carry_chain_1[j+1] = group_g[j] | (group_p[j] & carry_chain_1[j]);

                // Sum computation for both cases
                // Sum = P XOR carry_in (since P = a XOR b)
                assign sum_0[j] = group_p[j] ^ carry_chain_0[j];
                assign sum_1[j] = group_p[j] ^ carry_chain_1[j];
            end

            // Determine if this group propagates carry (all bits are propagate)
            // Select the appropriate carry-out and sum bits based on actual carry-in
            // This selection happens after both paths have computed, eliminating carry propagation delay
            wire actual_cin = group_carry[i];  // Actual carry-in to this group
            wire selected_cout = actual_cin ? carry_chain_1[CURRENT_GROUP_SIZE] : carry_chain_0[CURRENT_GROUP_SIZE];

            // Carry-out is fully determined by the bit-level generate/propagate chain
            // for the actual carry-in. Using the precomputed carry chains is correct
            // for all input patterns (including alternating patterns like 0x5555.. +
            // 0xAAAA..), so keep this selection simple.
            assign group_carry[i+1] = selected_cout;

            // Select sum bits based on actual carry-in
            // Multiplex the pre-computed sums based on the actual carry-in
            for (j = 0; j < CURRENT_GROUP_SIZE; j = j + 1) begin : sum_selection
                // Select sum_1 if carry-in is 1, else sum_0
                assign sum[START_IDX + j] = actual_cin ? sum_1[j] : sum_0[j];
            end
        end
    endgenerate

endmodule

