/**
 * Parameterized Radix Carry Lookahead Adder
 * 
 * This module implements a radix-based carry lookahead adder that groups bits
 * into fixed-size radix groups (4, 8, 16, or 32 bits). Each group computes
 * carries in parallel, and groups are connected sequentially. Higher radix
 * values reduce delay but increase area and fanout.
 * 
 * Algorithm:
 *   - Operands are divided into groups based on RADIX_MODE
 *   - Within each group, all carries are computed in parallel using CLA equations
 *   - Groups are connected sequentially (carry propagates between groups)
 *   - Radix-4: 4-bit groups, Radix-8: 8-bit groups, etc.
 * 
 * Radix Modes:
 *   - Radix-4 (00): 4-bit groups - balanced speed/area
 *   - Radix-8 (01): 8-bit groups - faster, more area
 *   - Radix-16 (10): 16-bit groups - very fast, large area
 *   - Radix-32 (11): 32-bit groups - fastest, largest area (single group for 32-bit width)
 * 
 * Characteristics:
 *   - Area: Increases with radix (more parallel logic per group)
 *   - Delay: O(n/RADIX_SIZE) - decreases with radix
 *   - Fanout: Increases with radix (more gates per group)
 *   - Use case: Medium-to-large adders where specific radix optimizes design goals
 * 
 * Trade-offs:
 *   - Higher radix = faster but larger area and higher fanout
 *   - Lower radix = smaller area but slower
 *   - Radix-4 is often a good balance for many applications
 * 
 * Note: DATA_WIDTH should be a power of 2 and >= 32 for optimal operation
 * 
 * @param DATA_WIDTH Width of input operands and sum output (must be power of 2 and >= 32, default: 32)
 * @param RADIX_MODE Radix mode: 00=Radix-4, 01=Radix-8, 10=Radix-16, 11=Radix-32 (default: 11)
 */
module radix_carry_lookahead_adder #(
    parameter DATA_WIDTH = 32,   // Width of the operands (must be power of 2 and >= 32)
    parameter RADIX_MODE = 2'b11 // Radix mode: 00=Radix-4, 01=Radix-8, 10=Radix-16, 11=Radix-32
) (
    input wire [DATA_WIDTH-1:0] a,        // First operand
    input wire [DATA_WIDTH-1:0] b,        // Second operand
    input wire cin,                       // Carry-in
    output wire [DATA_WIDTH-1:0] sum,     // Sum output: a + b + cin
    output wire cout                      // Carry-out: indicates overflow
);

    // Note: DATA_WIDTH should be a power of 2 and >= 32 for optimal operation
    // Validation removed for synthesis compatibility

    // Generate and Propagate signals for each bit
    // These are computed independently and in parallel for all bits
    wire [DATA_WIDTH-1:0] g;          // Generate: G[i] = a[i] & b[i]
    wire [DATA_WIDTH-1:0] p;          // Propagate: P[i] = a[i] ^ b[i]

    // Generate P and G signals for each bit position
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : pg_bit_logic
            // Generate: carry is generated when both inputs are 1
            assign g[i] = a[i] & b[i];

            // Propagate: carry propagates when exactly one input is 1
            assign p[i] = a[i] ^ b[i];
        end
    endgenerate

    // Internal carry signals for each bit position
    // These are computed within groups and then used for sum computation
    wire [DATA_WIDTH-1:0] c_internal;

    // Mode-specific implementations
    // Each radix mode has its own optimized implementation
    generate
        // Radix-4 mode (00): 4-bit groups
        // Good balance between speed and area
        if (RADIX_MODE == 2'b00) begin : radix_4_mode
            // Group size is 4 bits
            localparam RADIX_4_GROUP_SIZE = 4;
            localparam RADIX_4_NUM_GROUPS = DATA_WIDTH / RADIX_4_GROUP_SIZE;

            // Carry signals between groups
            // group_carry[i] is the carry entering group i
            wire [RADIX_4_NUM_GROUPS:0] group_carry;
            assign group_carry[0] = cin;      // Input carry enters the first group
            assign cout = group_carry[RADIX_4_NUM_GROUPS]; // Output carry exits the last group

            for (i = 0; i < RADIX_4_NUM_GROUPS; i = i + 1) begin : radix4_groups
                // Calculate start and end indices for this group
                localparam START_IDX = i * RADIX_4_GROUP_SIZE;
                localparam END_IDX = START_IDX + RADIX_4_GROUP_SIZE - 1;

                // Extract group P and G signals
                // These are the P and G values for the 4 bits in this group
                wire [RADIX_4_GROUP_SIZE-1:0] group_p = p[END_IDX:START_IDX];
                wire [RADIX_4_GROUP_SIZE-1:0] group_g = g[END_IDX:START_IDX];
                wire [RADIX_4_GROUP_SIZE:0] group_c;  // Carries within this group

                // Initialize: carry entering this group
                assign group_c[0] = group_carry[i];

                // Radix-4 CLA logic: compute carries for 4-bit group
                // All carries are computed in parallel (not sequentially)
                // Each carry uses the standard CLA formula: c[i+1] = G[i] OR (P[i] AND c[i])
                assign group_c[1] = group_g[0] | (group_p[0] & group_c[0]);
                assign group_c[2] = group_g[1] | (group_p[1] & group_c[1]);
                assign group_c[3] = group_g[2] | (group_p[2] & group_c[2]);
                assign group_c[4] = group_g[3] | (group_p[3] & group_c[3]);

                // Output: carry leaving this group goes to next group
                assign group_carry[i+1] = group_c[4];

                // Assign internal carries for sum computation
                // These are the carry values entering each bit position
                assign c_internal[START_IDX] = group_c[0];
                assign c_internal[START_IDX+1] = group_c[1];
                assign c_internal[START_IDX+2] = group_c[2];
                assign c_internal[START_IDX+3] = group_c[3];
            end
        end

        // Radix-8 mode (01): 8-bit groups
        // Faster than Radix-4 but with more area and fanout
        else if (RADIX_MODE == 2'b01) begin : radix_8_mode
            localparam RADIX_8_GROUP_SIZE = 8;
            localparam RADIX_8_NUM_GROUPS = DATA_WIDTH / RADIX_8_GROUP_SIZE;

            // Carry signals between groups
            wire [RADIX_8_NUM_GROUPS:0] group_carry;
            assign group_carry[0] = cin;      // Input carry enters the first group
            assign cout = group_carry[RADIX_8_NUM_GROUPS]; // Output carry exits the last group

            for (i = 0; i < RADIX_8_NUM_GROUPS; i = i + 1) begin : radix8_groups
                localparam START_IDX = i * RADIX_8_GROUP_SIZE;
                localparam END_IDX = START_IDX + RADIX_8_GROUP_SIZE - 1;

                // Extract group P and G signals
                wire [RADIX_8_GROUP_SIZE-1:0] group_p = p[END_IDX:START_IDX];
                wire [RADIX_8_GROUP_SIZE-1:0] group_g = g[END_IDX:START_IDX];
                wire [RADIX_8_GROUP_SIZE:0] group_c;  // Carries within this group

                // Initialize: carry entering this group
                assign group_c[0] = group_carry[i];

                // Radix-8 CLA logic: compute carries for 8-bit group
                // All 8 carries computed sequentially but within a single group
                // This reduces inter-group delay compared to Radix-4
                assign group_c[1] = group_g[0] | (group_p[0] & group_c[0]);
                assign group_c[2] = group_g[1] | (group_p[1] & group_c[1]);
                assign group_c[3] = group_g[2] | (group_p[2] & group_c[2]);
                assign group_c[4] = group_g[3] | (group_p[3] & group_c[3]);
                assign group_c[5] = group_g[4] | (group_p[4] & group_c[4]);
                assign group_c[6] = group_g[5] | (group_p[5] & group_c[5]);
                assign group_c[7] = group_g[6] | (group_p[6] & group_c[6]);
                assign group_c[8] = group_g[7] | (group_p[7] & group_c[7]);

                // Output: carry leaving this group
                assign group_carry[i+1] = group_c[8];

                // Assign internal carries for sum computation
                genvar j;
                for (j = 0; j < RADIX_8_GROUP_SIZE; j = j + 1) begin : assign_radix8_carries
                    assign c_internal[START_IDX + j] = group_c[j];
                end
            end
        end

        // Radix-16 mode (10): 16-bit groups
        // Very fast but with large area and high fanout
        else if (RADIX_MODE == 2'b10) begin : radix_16_mode
            localparam RADIX_16_GROUP_SIZE = 16;
            localparam RADIX_16_NUM_GROUPS = DATA_WIDTH / RADIX_16_GROUP_SIZE;

            // Carry signals between groups
            wire [RADIX_16_NUM_GROUPS:0] group_carry;
            assign group_carry[0] = cin;      // Input carry enters the first group
            assign cout = group_carry[RADIX_16_NUM_GROUPS]; // Output carry exits the last group

            for (i = 0; i < RADIX_16_NUM_GROUPS; i = i + 1) begin : radix16_groups
                localparam START_IDX = i * RADIX_16_GROUP_SIZE;
                localparam END_IDX = START_IDX + RADIX_16_GROUP_SIZE - 1;

                // Extract group P and G signals
                wire [RADIX_16_GROUP_SIZE-1:0] group_p = p[END_IDX:START_IDX];
                wire [RADIX_16_GROUP_SIZE-1:0] group_g = g[END_IDX:START_IDX];
                wire [RADIX_16_GROUP_SIZE:0] group_c;  // Carries within this group

                // Initialize: carry entering this group
                assign group_c[0] = group_carry[i];

                // Radix-16 CLA logic: compute carries for 16-bit group
                // Uses a loop to compute all 16 carries
                // This reduces code duplication compared to explicit assignments
                genvar j;
                for (j = 0; j < RADIX_16_GROUP_SIZE; j = j + 1) begin : radix16_carry_calc
                    // Standard CLA formula: c[j+1] = G[j] OR (P[j] AND c[j])
                    assign group_c[j+1] = group_g[j] | (group_p[j] & group_c[j]);
                end

                // Output: carry leaving this group
                assign group_carry[i+1] = group_c[RADIX_16_GROUP_SIZE];

                // Assign internal carries for sum computation
                for (j = 0; j < RADIX_16_GROUP_SIZE; j = j + 1) begin : assign_radix16_carries
                    assign c_internal[START_IDX + j] = group_c[j];
                end
            end
        end

        // Radix-32 mode (11): 32-bit groups
        // For 32-bit width, this is a single 32-bit CLA group
        // For wider widths, multiple 32-bit groups are created
        // Maximum speed but also maximum area and fanout
        else begin : radix_32_mode
            localparam RADIX_32_GROUP_SIZE = 32;
            localparam RADIX_32_NUM_GROUPS = DATA_WIDTH / RADIX_32_GROUP_SIZE;

            // Carry signals between groups
            wire [RADIX_32_NUM_GROUPS:0] group_carry;
            assign group_carry[0] = cin;      // Input carry enters the first group
            assign cout = group_carry[RADIX_32_NUM_GROUPS]; // Output carry exits the last group

            for (i = 0; i < RADIX_32_NUM_GROUPS; i = i + 1) begin : radix32_groups
                localparam START_IDX = i * RADIX_32_GROUP_SIZE;
                localparam END_IDX = START_IDX + RADIX_32_GROUP_SIZE - 1;

                // Extract group P and G signals
                wire [RADIX_32_GROUP_SIZE-1:0] group_p = p[END_IDX:START_IDX];
                wire [RADIX_32_GROUP_SIZE-1:0] group_g = g[END_IDX:START_IDX];
                wire [RADIX_32_GROUP_SIZE:0] group_c;  // Carries within this group

                // Initialize: carry entering this group
                assign group_c[0] = group_carry[i];

                // Radix-32 CLA logic: compute carries for 32-bit group
                // All 32 carries computed sequentially within a single group
                // This is the fastest possible for 32-bit width (no inter-group delay)
                genvar j;
                for (j = 0; j < RADIX_32_GROUP_SIZE; j = j + 1) begin : radix32_carry_calc
                    // Standard CLA formula: c[j+1] = G[j] OR (P[j] AND c[j])
                    assign group_c[j+1] = group_g[j] | (group_p[j] & group_c[j]);
                end

                // Output: carry leaving this group goes to next group
                assign group_carry[i+1] = group_c[RADIX_32_GROUP_SIZE];

                // Assign internal carries for sum computation
                for (j = 0; j < RADIX_32_GROUP_SIZE; j = j + 1) begin : assign_radix32_carries
                    assign c_internal[START_IDX + j] = group_c[j];
                end
            end
        end

    endgenerate

    // Compute the sum bits
    // Sum = P XOR carry_in (since P = a XOR b, and sum = a XOR b XOR carry_in)
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : sum_logic
            // Final sum: XOR propagate signal with carry-in
            // This is equivalent to: sum[i] = a[i] XOR b[i] XOR c_internal[i]
            assign sum[i] = p[i] ^ c_internal[i];
        end
    endgenerate

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

