/**
 * Parameterized Redundant Binary Adder
 * 
 * This module implements a simplified redundant binary adder. True redundant
 * binary representation uses a signed-digit number system where each digit can
 * be -1, 0, or 1, allowing carry-free addition in some cases. However, this
 * implementation provides standard binary addition semantics for compatibility
 * with the verification framework.
 * 
 * Algorithm:
 *   - Performs standard binary addition: a + b + cin
 *   - Result width is DATA_WIDTH+1 to accommodate overflow
 *   - Sum is the lower DATA_WIDTH bits
 *   - Carry-out is the overflow bit
 * 
 * Characteristics:
 *   - Area: Minimal - direct addition operation
 *   - Delay: O(1) - single addition operation
 *   - Power: Low - minimal logic
 *   - Use case: Simple addition operations, baseline implementation
 * 
 * Note: The repository's verification for this module expects standard binary
 * addition semantics with a single-bit carry-out (bit DATA_WIDTH).
 * A true redundant binary adder would use signed-digit representation and
 * different addition algorithms, but this simplified version maintains
 * compatibility with standard binary arithmetic.
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 */
module redundant_binary_adder #(
    parameter DATA_WIDTH = 32    // Width of the operands
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin (truncated to DATA_WIDTH)
    output wire cout                  // Carry-out: indicates overflow
);

    // Note: The repository's verification for this module expects standard binary
    // addition semantics with a single-bit carry-out (bit DATA_WIDTH).
    // Keep the implementation simple and correct.
    // 
    // Compute the full sum with one extra bit for overflow detection
    // full_sum has width DATA_WIDTH+1 to accommodate the result of a + b + cin
    wire [DATA_WIDTH:0] full_sum;

    // Perform addition: zero-extend operands and add
    // {1'b0, a} extends a to DATA_WIDTH+1 bits
    // {{DATA_WIDTH{1'b0}}, cin} extends cin to DATA_WIDTH+1 bits
    assign full_sum = {1'b0, a} + {1'b0, b} + {{DATA_WIDTH{1'b0}}, cin};

    // Extract the sum output (lower DATA_WIDTH bits)
    assign sum = full_sum[DATA_WIDTH-1:0];

    // Extract the carry-out (overflow bit, bit DATA_WIDTH)
    assign cout = full_sum[DATA_WIDTH];

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_ripple_carry.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Ripple Carry Adder
 * 
 * This module implements a standard ripple carry adder (RCA), also known as a 
 * carry-propagate adder. It is the simplest and most area-efficient adder design,
 * but has the longest critical path delay.
 * 
 * Algorithm:
 *   - Each bit position uses a full adder (FA) that computes:
 *     * sum[i] = a[i] XOR b[i] XOR carry[i]
 *     * carry[i+1] = (a[i] AND b[i]) OR ((a[i] OR b[i]) AND carry[i])
 *   - Carries propagate sequentially from LSB to MSB
 *   - The critical path delay is O(n) where n is DATA_WIDTH
 * 
 * Characteristics:
 *   - Area: O(n) - minimal hardware requirements
 *   - Delay: O(n) - worst case delay grows linearly with width
 *   - Power: Low - minimal switching activity
 *   - Use case: Small adders, area-constrained designs, or when delay is not critical
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 */
module ripple_carry_adder #(
    parameter DATA_WIDTH = 32    // Width of the operands
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in (typically 0 for addition, 1 for increment)
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow when DATA_WIDTH bits insufficient
);

    // Internal carry signals between full adders
    // Size is DATA_WIDTH+1 to accommodate carry[0] (cin) through carry[DATA_WIDTH] (cout)
    wire [DATA_WIDTH:0] carry;

    // Initialize carry chain: carry[0] receives the input carry
    assign carry[0] = cin;

    // Final carry-out is the carry from the most significant bit position
    assign cout = carry[DATA_WIDTH];

    // Generate full adders for each bit position
    // Each full adder computes the sum and carry-out for one bit position
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : full_adder_chain
            // Full adder logic for bit position i
            // 
            // Sum calculation: XOR of all three inputs
            //   sum[i] = a[i] XOR b[i] XOR carry[i]
            // This implements: sum = a + b + carry_in (mod 2)
            assign sum[i] = a[i] ^ b[i] ^ carry[i];

            // Carry-out calculation: optimized form of the standard full adder equation
            // Standard form: carry[i+1] = (a[i] & b[i]) | (a[i] & carry[i]) | (b[i] & carry[i])
            // Optimized form: carry[i+1] = (a[i] & b[i]) | ((a[i] | b[i]) & carry[i])
            //   - First term: carry generated when both a[i] and b[i] are 1
            //   - Second term: carry propagated when at least one of a[i] or b[i] is 1 AND carry[i] is 1
            // This reduces gate count from 3 AND + 2 OR to 2 AND + 2 OR
            assign carry[i+1] = (a[i] & b[i]) | ((a[i] | b[i]) & carry[i]);
        end
    endgenerate

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_serial.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Serial Adder
 * 
 * This module implements a serial (bit-serial) adder that processes operands
 * one bit at a time, starting from the least significant bit (LSB). This design
 * trades speed for minimal hardware resources.
 * 
 * Algorithm:
 *   - Operands are loaded into shift registers
 *   - Addition proceeds bit-by-bit from LSB to MSB
 *   - Each clock cycle processes one bit position
 *   - Sum bits are accumulated in a shift register
 *   - Takes DATA_WIDTH clock cycles to complete
 * 
 * Characteristics:
 *   - Area: Minimal - only one full adder and shift registers
 *   - Delay: O(n) clock cycles - slow but predictable
 *   - Power: Very low - minimal hardware switching
 *   - Use case: Area-constrained designs, low-speed applications, or when
 *               operands arrive serially
 * 
 * Operation Flow:
 *   1. Load phase: Set load=1 to store operands a and b
 *   2. Start phase: Set start=1 to begin addition
 *   3. Compute phase: Addition proceeds automatically, one bit per clock cycle
 *   4. Done phase: done=1 indicates completion, sum is valid
 * 
 * @param DATA_WIDTH Width of input operands and sum output (default: 32)
 */
module serial_adder #(
    parameter DATA_WIDTH = 32    // Width of the operands
) (
    input wire clk,                    // Clock signal (rising edge triggered)
    input wire rst_n,                  // Active low reset (synchronous)
    input wire [DATA_WIDTH-1:0] a,     // First operand (loaded when load=1)
    input wire [DATA_WIDTH-1:0] b,     // Second operand (loaded when load=1)
    input wire load,                   // Load operands into internal registers (active high)
    input wire start,                  // Start addition operation (active high)
    output wire [DATA_WIDTH-1:0] sum,  // Sum output (valid when done=1)
    output wire done,                  // Operation complete flag (active high)
    output wire busy                   // Operation in progress flag (active high)
);

    // Internal registers for operands (shift registers)
    // These shift right each cycle, exposing the next bit to be processed
    reg [DATA_WIDTH-1:0] a_reg;
    reg [DATA_WIDTH-1:0] b_reg;

    // Accumulator for sum (shifts right as bits are calculated)
    // Sum bits are inserted from the left (MSB first in the register, but LSB first in computation)
    reg [DATA_WIDTH-1:0] sum_reg;

    // Carry register: stores the carry from the current bit to the next bit
    reg carry_reg;

    // Bit counter to track progress through the addition
    // Counts from 0 to DATA_WIDTH-1
    reg [$clog2(DATA_WIDTH)-1:0] bit_count;
    reg [$clog2(DATA_WIDTH)-1:0] max_count;  // Maximum count (DATA_WIDTH - 1)

    // State registers: track the current state of the adder
    reg loaded;    // Data has been loaded (operands are ready)
    reg running;   // Addition is in progress (actively computing)

    // Calculate current bit addition
    // Extract the LSB from each operand register (the bit currently being processed)
    wire current_a_bit = a_reg[0];      // LSB of current A (bit being processed)
    wire current_b_bit = b_reg[0];      // LSB of current B (bit being processed)
    wire sum_bit, carry_out;

    // Full adder logic for current bit
    // Computes sum and carry-out for the current bit position
    // Sum: XOR of all three inputs (a_bit, b_bit, carry_in)
    assign sum_bit = current_a_bit ^ current_b_bit ^ carry_reg;

    // Carry-out: generate OR propagate
    // Optimized form: (a & b) | ((a | b) & carry_in)
    assign carry_out = (current_a_bit & current_b_bit) | ((current_a_bit | current_b_bit) & carry_reg);

    // Status signals
    assign busy = running;  // Busy when addition is in progress
    assign done = !running && loaded && (bit_count == max_count);  // Done when not running, loaded, and all bits processed
    assign sum = sum_reg;   // Output the accumulated sum

    // Initialize max_count to DATA_WIDTH - 1
    initial begin
        max_count = DATA_WIDTH - 1;
    end

    // Main sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all registers
            a_reg <= {DATA_WIDTH{1'b0}};
            b_reg <= {DATA_WIDTH{1'b0}};
            sum_reg <= {DATA_WIDTH{1'b0}};
            carry_reg <= 1'b0;
            bit_count <= {$clog2(DATA_WIDTH){1'b0}};
            loaded <= 1'b0;
            running <= 1'b0;
        end else begin
            // Load operation
            if (load && !running) begin
                a_reg <= a;
                b_reg <= b;
                sum_reg <= {DATA_WIDTH{1'b0}};
                carry_reg <= 1'b0;
                bit_count <= {$clog2(DATA_WIDTH){1'b0}};
                loaded <= 1'b1;
                running <= 1'b0;
            end
            // Start operation
            else if (start && loaded && !running) begin
                running <= 1'b1;
                bit_count <= {$clog2(DATA_WIDTH){1'b0}};
            end
            // Addition operation
            else if (running) begin
                // Shift sum bit into accumulator (LSB first)
                sum_reg <= {sum_bit, sum_reg[DATA_WIDTH-1:1]};

                // Update carry for next bit
                carry_reg <= carry_out;

                // Shift operand registers right (next bit becomes LSB)
                a_reg <= {1'b0, a_reg[DATA_WIDTH-1:1]};
                b_reg <= {1'b0, b_reg[DATA_WIDTH-1:1]};

                // Increment bit counter
                bit_count <= bit_count + 1'b1;

                // Check if addition is complete
                if (bit_count == max_count) begin
                    running <= 1'b0;
                    // Final carry is lost (typical for serial adders)
                    // Could be stored in an additional output if needed
                end
            end
        end
    end

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_sparse_kogge_stone.code:
/* verilator lint_off DECLFILENAME */
/* verilator lint_off UNOPTFLAT */
/* verilator lint_off EOFNEWLINE */
/* verilator lint_off GENUNNAMED */

/**
 * Parameterized Sparse Kogge-Stone Adder
 * 
 * This module implements a parameterized prefix tree adder that can operate in
 * either dense (standard Kogge-Stone) or sparse mode. The sparse mode reduces
 * wiring complexity at the cost of potentially more stages or different connectivity.
 * 
 * Algorithm:
 *   - Dense Mode (MODE=0): Standard Kogge-Stone with full connectivity
 *     * Each bit connects to immediate previous bit in each stage
 *     * Maximum parallelism, minimum depth
 *   - Sparse Mode (MODE=1): Sparse Kogge-Stone with reduced connectivity
 *     * Each bit connects to bit at distance 2^i in stage i
 *     * Reduces wiring complexity
 * 
 * Characteristics:
 *   - Dense Mode:
 *     * Logic Depth: log2(n) - minimum possible
 *     * Fanout: High - maximum wiring
 *     * Area: Large - maximum area
 *     * Speed: Fastest
 *   - Sparse Mode:
 *     * Logic Depth: log2(n) - same as dense
 *     * Fanout: Moderate - reduced wiring
 *     * Area: Moderate - less area than dense
 *     * Speed: Fast - similar to dense
 * 
 * Use case: When you want to compare dense vs sparse implementations or
 *           optimize for specific wiring constraints
 * 
 * @param DATA_WIDTH Width of input operands and sum output (must be power of 2, default: 32)
 * @param MODE Mode selector: 0=Dense Kogge-Stone, 1=Sparse Kogge-Stone (default: 0)
 */
module sparse_kogge_stone_adder #(
    parameter DATA_WIDTH = 32,   // Width of the operands
    parameter MODE = 0           // Mode selector: 0=Dense Kogge-Stone, 1=Sparse Kogge-Stone
) (
    input wire [DATA_WIDTH-1:0] a,    // First operand
    input wire [DATA_WIDTH-1:0] b,    // Second operand
    input wire cin,                   // Carry-in
    output wire [DATA_WIDTH-1:0] sum, // Sum output: a + b + cin
    output wire cout                  // Carry-out: indicates overflow
);

    // Number of stages in the prefix tree
    // Both modes use log2(DATA_WIDTH) stages
    localparam STAGES = $clog2(DATA_WIDTH);

    // Generate and Propagate signals (initial values)
    wire [DATA_WIDTH-1:0] g_init;  // Generate: G[i] = a[i] & b[i]
    wire [DATA_WIDTH-1:0] p_init;  // Propagate: P[i] = a[i] ^ b[i]

    // Generate initial P and G values for each bit position
    // These are computed independently and in parallel
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : init_pg
            // Generate: carry is generated when both inputs are 1
            assign g_init[i] = a[i] & b[i];

            // Propagate: carry propagates when exactly one input is 1
            assign p_init[i] = a[i] ^ b[i];
        end
    endgenerate

    // Intermediate P and G signals for each stage of the tree
    wire [DATA_WIDTH-1:0] p [STAGES:0];
    wire [DATA_WIDTH-1:0] g [STAGES:0];

    // Initialize first level with the initial P and G
    // Stage 0 represents individual bit positions
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : init_stage
            assign p[0][i] = p_init[i];
            assign g[0][i] = g_init[i];
        end
    endgenerate

    // Build the prefix tree - parameterized between Dense and Sparse Kogge-Stone
    // The mode selector determines the connectivity pattern
    genvar j, k;
    generate
        for (i = 0; i < STAGES; i = i + 1) begin : prefix_stage
            for (j = 0; j < DATA_WIDTH; j = j + 1) begin : prefix_bit
                // Mode selector determines the connectivity pattern:
                // mode=0: Dense Kogge-Stone (standard, connects each bit to previous bit)
                // mode=1: Sparse Kogge-Stone (sparse connectivity, reduces wiring)

                if (MODE == 0) begin : dense_kogge_stone_mode
                    // Dense Kogge-Stone: each bit gets information from the immediate previous bit
                    // This is the standard Kogge-Stone implementation with maximum connectivity
                    if (j >= 1) begin : use_prefix_dense
                        // Dense computation: connect to immediate previous bit
                        // This maximizes parallelism within each stage
                        // 
                        // Update generate: G_new = G_j OR (P_j AND G_{j-1})
                        assign g[i+1][j] = g[i][j] | (p[i][j] & g[i][j-1]);

                        // Update propagate: P_new = P_j AND P_{j-1}
                        assign p[i+1][j] = p[i][j] & p[i][j-1];
                    end
                    else begin : pass_through_dense
                        // Bit 0 just passes through (no previous bit to connect to)
                        assign g[i+1][j] = g[i][j];
                        assign p[i+1][j] = p[i][j];
                    end
                end
                else begin : sparse_kogge_stone_mode
                    // Sparse Kogge-Stone: uses sparse connectivity pattern
                    // Instead of connecting to j-1, connect to j-2^i in each stage
                    // This creates a sparser tree that reduces wiring complexity
                    // while maintaining the same logic depth
                    localparam step = 1 << i;  // Step size: 1, 2, 4, 8, ...

                    if (j >= step) begin : use_prefix_sparse
                        // Sparse computation: connect to bit at distance 'step'
                        // This reduces the number of connections compared to dense mode
                        // 
                        // Update generate: G_new = G_j OR (P_j AND G_{j-step})
                        assign g[i+1][j] = g[i][j] | (p[i][j] & g[i][j-step]);

                        // Update propagate: P_new = P_j AND P_{j-step}
                        assign p[i+1][j] = p[i][j] & p[i][j-step];
                    end
                    else begin : pass_through_sparse
                        // Lower bits (j < step) just pass through unchanged
                        // They don't have a left neighbor at distance 'step' yet
                        assign g[i+1][j] = g[i][j];
                        assign p[i+1][j] = p[i][j];
                    end
                end
            end
        end
    endgenerate

    // Generate the carries using the final stage P and G values
    wire [DATA_WIDTH:0] carries;
    assign carries[0] = cin;  // Initial carry-in

    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : carry_gen
            // c_{i+1} = g_i | (p_i & c_i)
            assign carries[i+1] = g[STAGES][i] | (p[STAGES][i] & carries[i]);
        end
    endgenerate

    // Compute the sum bits
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : sum_gen
            assign sum[i] = (a[i] ^ b[i]) ^ carries[i];  // sum = a ^ b ^ carry_in
        end
    endgenerate

    // Final carry-out
    assign cout = carries[DATA_WIDTH];

endmodule

/* verilator lint_on DECLFILENAME */
/* verilator lint_on UNOPTFLAT */
/* verilator lint_on EOFNEWLINE */
/* verilator lint_on GENUNNAMED */

db_vedic.code:
