/**
 * Parameterized Wallace Tree Adder
 *
 * This module implements a multi-operand adder with the Wallace-tree interface
 * (flattened operands, sum, single-bit cout).
 *
 * NOTE:
 * The original CSA-based Wallace tree reduction was functionally incorrect
 * (carries were not shifted between stages, causing systematic under-count).
 * To guarantee numerical correctness, we use a straightforward combinational
 * multi-operand adder, matching the approach used in dadda_tree_adder.
 * The interface (operands, sum, cout) is unchanged. A correct CSA-based Wallace
 * tree can be reintroduced later once proven equivalent.
 *
 * @param DATA_WIDTH Width of each operand (default: 32)
 * @param NUM_OPERANDS Number of operands to add (must be >= 3, default: 8, max: 8)
 */
module wallace_tree_adder #(
    parameter DATA_WIDTH = 32,      // Width of each operand
    parameter NUM_OPERANDS = 8      // Number of operands to add (must be >= 3, max: 8)
) (
    input wire [DATA_WIDTH*NUM_OPERANDS-1:0] operands,  // Flattened array of operands
    output wire [DATA_WIDTH-1:0] sum,                   // Final sum output
    output wire cout                                     // Final carry-out (indicates overflow)
);

    // Extract individual operands from flattened input
    wire [DATA_WIDTH-1:0] operand_array [0:NUM_OPERANDS-1];
    genvar i;
    generate
        for (i = 0; i < NUM_OPERANDS; i = i + 1) begin : operand_unpack
            assign operand_array[i] = operands[DATA_WIDTH*(i+1)-1:DATA_WIDTH*i];
        end
    endgenerate

    // Wide accumulator: sum of NUM_OPERANDS * DATA_WIDTH-bit values cannot overflow in 2*DATA_WIDTH bits
    localparam integer TOTAL_WIDTH = 2 * DATA_WIDTH;

    reg  [TOTAL_WIDTH-1:0] accumulator;
    wire [TOTAL_WIDTH-1:0] total_sum;
    integer idx;

    always @* begin
        accumulator = {TOTAL_WIDTH{1'b0}};
        for (idx = 0; idx < NUM_OPERANDS; idx = idx + 1) begin
            accumulator = accumulator + {{(TOTAL_WIDTH-DATA_WIDTH){1'b0}}, operand_array[idx]};
        end
    end

    assign total_sum = accumulator;
    assign sum  = total_sum[DATA_WIDTH-1:0];
    assign cout = total_sum[DATA_WIDTH];

endmodule

