module hysteresis_triple_path_adder #(
    parameter integer DATA_WIDTH = 16,
    parameter integer BLOCK_SIZE = 4
) (
    input  wire [DATA_WIDTH-1:0] a,
    input  wire [DATA_WIDTH-1:0] b,
    input  wire                  cin,
    output wire [DATA_WIDTH-1:0] sum,
    output wire                  cout
);
    localparam integer NUM_BLOCKS = (DATA_WIDTH + BLOCK_SIZE - 1) / BLOCK_SIZE;

    wire [NUM_BLOCKS:0]       block_carry;
    wire [2*(NUM_BLOCKS+1)-1:0] mode_chain;

    assign block_carry[0]  = cin;
    assign mode_chain[1:0] = 2'd1;

    genvar bi;
    generate
        for (bi = 0; bi < NUM_BLOCKS; bi = bi + 1) begin : gen_block
            localparam integer B_START = bi * BLOCK_SIZE;
            localparam integer BW = ((B_START + BLOCK_SIZE) <= DATA_WIDTH)
                ? BLOCK_SIZE
                : (DATA_WIDTH - B_START);
            localparam integer LOW_TH  = (BW >= 2) ? (BW / 2) : 1;
            localparam integer HIGH_TH = BW + 1;
            localparam integer HYST_M  = (BW >= 3) ? (BW / 3) : 1;

            wire [BW-1:0] a_blk = a[B_START +: BW];
            wire [BW-1:0] b_blk = b[B_START +: BW];
            wire [BW-1:0] p_bits = a_blk ^ b_blk;
            wire [BW-1:0] g_bits = a_blk & b_blk;
            wire [BW-1:0] k_bits = ~(a_blk | b_blk);
            wire          cin_blk = block_carry[bi];
            wire [1:0]    prev_mode = mode_chain[2*bi +: 2];

            reg  [1:0]    next_mode;
            reg  [BW-1:0] blk_sum;
            reg           blk_cout;

            integer j;
            integer p_cnt;
            integer g_cnt;
            integer k_cnt;
            integer score;
            integer c_rip;
            integer c0;
            integer c1;
            integer grp_g;
            reg [BW-1:0] rip_sum;
            reg [BW-1:0] sum0;
            reg [BW-1:0] sum1;
            wire         grp_p = &p_bits;

            always @* begin
                p_cnt = 0;
                g_cnt = 0;
                k_cnt = 0;
                c_rip = cin_blk;
                c0    = 0;
                c1    = 1;
                grp_g = 0;

                for (j = 0; j < BW; j = j + 1) begin
                    p_cnt = p_cnt + p_bits[j];
                    g_cnt = g_cnt + g_bits[j];
                    k_cnt = k_cnt + k_bits[j];

                    rip_sum[j] = p_bits[j] ^ c_rip[0];
                    c_rip      = g_bits[j] | (p_bits[j] & c_rip);

                    sum0[j]    = p_bits[j] ^ c0[0];
                    c0         = g_bits[j] | (p_bits[j] & c0);

                    sum1[j]    = p_bits[j] ^ c1[0];
                    c1         = g_bits[j] | (p_bits[j] & c1);

                    grp_g      = g_bits[j] | (p_bits[j] & grp_g);
                end

                score = (2 * g_cnt) + p_cnt - (2 * k_cnt);

                next_mode = prev_mode;
                if (prev_mode == 2'd0) begin
                    if (score >= HIGH_TH) begin
                        next_mode = 2'd2;
                    end else if (score >= (LOW_TH + HYST_M)) begin
                        next_mode = 2'd1;
                    end
                end else if (prev_mode == 2'd1) begin
                    if (score >= (HIGH_TH + HYST_M)) begin
                        next_mode = 2'd2;
                    end else if (score < (LOW_TH - HYST_M)) begin
                        next_mode = 2'd0;
                    end
                end else begin
                    if (score < LOW_TH) begin
                        next_mode = 2'd0;
                    end else if (score < (HIGH_TH - HYST_M)) begin
                        next_mode = 2'd1;
                    end
                end

                if (next_mode == 2'd2) begin
                    blk_sum  = rip_sum;
                    blk_cout = grp_g | (grp_p & cin_blk);
                end else if (next_mode == 2'd1) begin
                    blk_sum  = cin_blk ? sum1 : sum0;
                    blk_cout = cin_blk ? c1[0] : c0[0];
                end else begin
                    blk_sum  = rip_sum;
                    blk_cout = c_rip[0];
                end
            end

            assign sum[B_START +: BW]          = blk_sum;
            assign block_carry[bi + 1]         = blk_cout;
            assign mode_chain[2*(bi + 1) +: 2] = next_mode;
        end
    endgenerate

    assign cout = block_carry[NUM_BLOCKS];
endmodule

