module phase_quorum_inertia_adder #(
    parameter integer DATA_WIDTH = 16,
    parameter integer BLOCK_SIZE = 4
) (
    input  wire [DATA_WIDTH-1:0] a,
    input  wire [DATA_WIDTH-1:0] b,
    input  wire                  cin,
    output reg  [DATA_WIDTH-1:0] sum,
    output reg                   cout
);
    integer block_start;
    integer block_index;
    integer bit_count;
    integer bit_index;
    integer carry_local;
    integer carry0;
    integer carry1;
    integer carry;
    integer next_carry;
    integer prev_score;
    integer prev_delta;
    integer inertia;
    integer mode_state;
    integer sticky_select;
    integer score_core;
    integer delta;
    integer accel;
    integer fused_score;
    integer high_on;
    integer high_off;
    integer med_on;
    integer med_off;
    integer p_count;
    integer g_count;
    integer k_count;
    integer bias;
    integer quorum;
    integer phase;
    integer propagate_group;
    reg [BLOCK_SIZE-1:0] p_bits;
    reg [BLOCK_SIZE-1:0] g_bits;
    reg [BLOCK_SIZE-1:0] k_bits;
    reg [BLOCK_SIZE-1:0] block_sum;
    reg [BLOCK_SIZE-1:0] sum0;
    reg [BLOCK_SIZE-1:0] sum1;

    always @* begin
        sum = {DATA_WIDTH{1'b0}};
        carry = cin;
        prev_score = 0;
        prev_delta = 0;
        inertia = 0;
        mode_state = 0;
        sticky_select = 0;

        for (block_start = 0; block_start < DATA_WIDTH; block_start = block_start + BLOCK_SIZE) begin
            block_index = block_start / BLOCK_SIZE;
            bit_count = ((block_start + BLOCK_SIZE) <= DATA_WIDTH) ? BLOCK_SIZE : (DATA_WIDTH - block_start);
            p_bits = {BLOCK_SIZE{1'b0}};
            g_bits = {BLOCK_SIZE{1'b0}};
            k_bits = {BLOCK_SIZE{1'b0}};
            block_sum = {BLOCK_SIZE{1'b0}};
            sum0 = {BLOCK_SIZE{1'b0}};
            sum1 = {BLOCK_SIZE{1'b0}};
            p_count = 0;
            g_count = 0;
            k_count = 0;
            propagate_group = 1;

            for (bit_index = 0; bit_index < BLOCK_SIZE; bit_index = bit_index + 1) begin
                if ((bit_index < bit_count) && ((block_start + bit_index) < DATA_WIDTH)) begin
                    p_bits[bit_index] = a[block_start + bit_index] ^ b[block_start + bit_index];
                    g_bits[bit_index] = a[block_start + bit_index] & b[block_start + bit_index];
                    k_bits[bit_index] = ~(a[block_start + bit_index] | b[block_start + bit_index]);
                end
            end

            carry_local = carry;
            carry0 = 0;
            carry1 = 1;
            for (bit_index = 0; bit_index < BLOCK_SIZE; bit_index = bit_index + 1) begin
                if (bit_index < bit_count) begin
                    propagate_group = propagate_group & p_bits[bit_index];
                    p_count = p_count + p_bits[bit_index];
                    g_count = g_count + g_bits[bit_index];
                    k_count = k_count + k_bits[bit_index];

                    block_sum[bit_index] = p_bits[bit_index] ^ carry_local[0];
                    carry_local = g_bits[bit_index] | (p_bits[bit_index] & carry_local);

                    sum0[bit_index] = p_bits[bit_index] ^ carry0[0];
                    carry0 = g_bits[bit_index] | (p_bits[bit_index] & carry0);
                    sum1[bit_index] = p_bits[bit_index] ^ carry1[0];
                    carry1 = g_bits[bit_index] | (p_bits[bit_index] & carry1);
                end
            end

            bias = g_count - k_count;
            quorum = ((g_count > k_count) ? g_count : k_count) * 2 >= bit_count ? 1 : 0;
            if ((block_index % 4) < 2) begin
                phase = 2;
            end else begin
                phase = -1;
            end

            score_core = p_count + ((bias >= 0) ? bias : -bias) + (2 * quorum);
            delta = score_core - prev_score;
            accel = delta - prev_delta;
            prev_delta = delta;
            prev_score = score_core;

            if (delta >= 2) begin
                if (inertia < 6) begin
                    inertia = inertia + 1;
                end
            end else if (delta <= -2) begin
                if (inertia > -6) begin
                    inertia = inertia - 1;
                end
            end else begin
                if (inertia > 0) begin
                    inertia = inertia - 1;
                end else if (inertia < 0) begin
                    inertia = inertia + 1;
                end
            end

            fused_score = score_core + delta + accel + inertia + phase;
            high_on = (bit_count + 4 > 9) ? (bit_count + 4) : 9;
